import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderInput } from 'claude-code'

import type { Draft, Mode, PerMode, Post, Status, View } from '../types'
import { encodeQr, qrRows, qrSvg } from './qr'
import {
  API,
  CALLBACK_PORT,
  CALLBACK_SERVER,
  POST_LIMIT,
  REDIRECT_URI,
  EXPANSIONS,
  MEDIA_FIELDS,
  intentUrl,
  isMediaUrl,
  mediaVariant,
  TWEET_FIELDS,
  USER_FIELDS,
  authorizeUrl,
  canLike,
  canPost,
  clampResults,
  compactCount,
  createPkce,
  decodeSecret,
  describeApiError,
  encodeSecret,
  formEncode,
  IMAGE_LIMIT,
  IMAGE_TYPES,
  hasScope,
  imagePathProblem,
  isClientId,
  parseLists,
  parsePostArgs,
  parseTrends,
  mergePosts,
  normalizeTag,
  parseClientIdArgs,
  parseQuery,
  parseProfile,
  parseSingle,
  parseTimeline,
  profileText,
  joinedText,
  PROFILE_FIELDS,
  clip,
  postBadges,
  postText,
  postUrl,
  refreshIntervalMs,
  relativeTime,
  segments,
  tagQuery,
  targetOf,
  tokensFrom,
  weightedLength,
} from './x-api'
import type { HttpLike, Tokens } from './x-api'

const PANE = 'x-timeline'
const TITLE = '𝕏'
const KEPT = 300
const SHOWN_AS_TEXT = 15
// Tools of the host, found at session start: macOS ships `security`,
// `open` and a python3; Linux has `secret-tool` (libsecret) and `xdg-open`.
type Platform = { secrets: 'keychain' | 'libsecret' | null; opener: string; python: string; cacheRoot: string | null }
let platform: Platform = { secrets: 'keychain', opener: '/usr/bin/open', python: '/usr/bin/python3', cacheRoot: null }
const KEYCHAIN_SERVICE = 'claude-x-timeline'
const KEYCHAIN_ACCOUNT = 'oauth-token'
const AUTO_STEPS = [0, 5, 15, 30]
// X's own colors: the blue of links and the active tab, the pink of a
// like, the green of a repost.
const ACCENT = '#1d9bf0'
const PINK = '#f91880'
const GREEN = '#00ba7c'
const AVATAR_COLORS = ['#1d9bf0', '#f91880', '#00ba7c', '#7856ff', '#ff7a00', '#ffd400', '#e0245e', '#17bf63']
// Where a command that posts may come from: a person's own message, never
// automation (scheduled triggers, peers, channels, notifications).
const PERSON_ORIGINS = ['composer', 'bridge', 'sdk']

const INITIAL: Status = {
  auth: 'unknown',
  mode: 'home',
  isLoading: false,
  error: null,
  notice: null,
  fetchedAt: { home: null, mentions: null, tags: null, bookmarks: null, view: null },
  account: null,
  authorizeUrl: null,
  autoMinutes: 0,
  canPost: false,
  canLike: false,
  newIds: [],
  unread: { home: 0, mentions: 0, tags: 0, bookmarks: 0, view: 0 },
  liked: [],
  reposted: [],
  bookmarked: [],
  followed: [],
  muted: [],
  deleteAsk: null,
  repostAsk: null,
  shown: { home: [], mentions: [], tags: [], bookmarks: [], view: [] },
  view: null,
  backTo: 'home',
  cursor: 0,
  imagesReady: [],
  liveTail: null,
  chatLimit: 10,
  hasMore: { home: true, mentions: true, tags: true, bookmarks: false, view: false },
  tags: [],
  activeTag: null,
  qrFor: null,
}
const EMPTY_DRAFT: Draft = { text: '', replyTo: null, quoteOf: null, images: [], isConfirming: false, isPosting: false }

const posts = atom({ plugin: 'x-timeline', key: 'posts' } as const, [])
const mentions = atom({ plugin: 'x-timeline', key: 'mentions' } as const, [])
const tagPosts = atom({ plugin: 'x-timeline', key: 'tagPosts' } as const, [])
const viewPosts = atom({ plugin: 'x-timeline', key: 'viewPosts' } as const, [])
const bookmarkPosts = atom({ plugin: 'x-timeline', key: 'bookmarkPosts' } as const, [])
const status = atom({ plugin: 'x-timeline', key: 'status' } as const, INITIAL)
const draft = atom({ plugin: 'x-timeline', key: 'draft' } as const, EMPTY_DRAFT)

type Engine = EngineInterface

// The tokens live in the macOS Keychain and in this module's memory only:
// never in $.state, $.store, logs or the pane.
let tokens: Tokens | null = null
let refreshing: Promise<Tokens | null> | null = null
let isFetching = false
let isLoggingIn = false
let pendingLogin: { verifier: string; state: string; clientId: string } | null = null
let maxResults = 20
let defaultAutoMinutes = 0
let autoTimer: { cancel: () => void } | null = null
// Where post pictures are kept as PNG files a terminal reads itself.
let mediaDir: string | null = null
const mediaInFlight = new Set<string>()

// Values kept from an older version of this mod read as the current shape.
function perMode<T>(base: PerMode<T>, kept: Partial<PerMode<T>> | undefined): PerMode<T> {
  return { ...base, ...kept }
}

async function readStatus($: Engine): Promise<Status> {
  const kept = await read($, status)

  return {
    ...INITIAL,
    ...kept,
    fetchedAt: perMode(INITIAL.fetchedAt, kept.fetchedAt),
    unread: perMode(INITIAL.unread, kept.unread),
    hasMore: perMode(INITIAL.hasMore, kept.hasMore),
    shown: perMode(INITIAL.shown, kept.shown),
  }
}

async function readDraft($: Engine): Promise<Draft> {
  return { ...EMPTY_DRAFT, ...(await read($, draft)) }
}

function setStatus($: Engine, patch: Partial<Status>) {
  return update($, status, s => ({ ...INITIAL, ...s, ...patch }))
}

function readList($: Engine, mode: Mode): Promise<Post[]> {
  if (mode === 'home') return read($, posts)
  if (mode === 'view') return read($, viewPosts)
  if (mode === 'bookmarks') return read($, bookmarkPosts)

  return mode === 'mentions' ? read($, mentions) : read($, tagPosts)
}

function updateList($: Engine, mode: Mode, fn: (list: Post[]) => Post[]) {
  if (mode === 'home') return update($, posts, fn)
  if (mode === 'view') return update($, viewPosts, fn)
  if (mode === 'bookmarks') return update($, bookmarkPosts, fn)

  return mode === 'mentions' ? update($, mentions, fn) : update($, tagPosts, fn)
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

async function detectPlatform($: Engine): Promise<void> {
  const has = (path: string) => $.fs.exists(path).catch(() => false)
  const home = (await $.env.get('HOME')) ?? null
  if (await has('/usr/bin/security')) {
    platform = { secrets: 'keychain', opener: '/usr/bin/open', python: '/usr/bin/python3', cacheRoot: home ? `${home}/Library/Caches` : null }

    return
  }
  const secretTool = (await has('/usr/bin/secret-tool')) ? 'libsecret' : null
  platform = { secrets: secretTool, opener: 'xdg-open', python: 'python3', cacheRoot: home ? `${home}/.cache` : null }
}

async function openUrl($: Engine, url: string): Promise<void> {
  await $.process.run([platform.opener, url]).catch(() => undefined)
}

async function loadTokens($: Engine): Promise<Tokens | null> {
  const found =
    platform.secrets === 'keychain'
      ? await $.process.run(['/usr/bin/security', 'find-generic-password', '-s', KEYCHAIN_SERVICE, '-a', KEYCHAIN_ACCOUNT, '-w'])
      : platform.secrets === 'libsecret'
        ? await $.process.run(['/usr/bin/secret-tool', 'lookup', 'service', KEYCHAIN_SERVICE, 'account', KEYCHAIN_ACCOUNT])
        : null

  return found?.exitCode === 0 ? decodeSecret(found.stdout) : null
}

async function saveTokens($: Engine, next: Tokens): Promise<void> {
  // The secret goes over stdin to `security -i`, never on a command line.
  // base64url keeps it free of quotes and spaces.
  const secret = encodeSecret(next)
  // No secret store, no saving: a token is never written to a plain file.
  if (!platform.secrets) throw new Error('トークンを安全に保存できる場所がありません（macOS のキーチェーンか Linux の secret-tool が必要です）')
  if (platform.secrets === 'keychain') {
    await $.process.run(['/usr/bin/security', '-i'], {
      stdin: `add-generic-password -U -s "${KEYCHAIN_SERVICE}" -a "${KEYCHAIN_ACCOUNT}" -l "Claude X timeline" -w "${secret}"\n`,
    })
  } else {
    await $.process.run(['/usr/bin/secret-tool', 'store', '--label=Claude X timeline', 'service', KEYCHAIN_SERVICE, 'account', KEYCHAIN_ACCOUNT], { stdin: secret })
  }
  const stored = await loadTokens($)
  if (stored?.accessToken !== next.accessToken) throw new Error('キーチェーンにトークンを保存できませんでした')
  tokens = next
}

async function forgetTokens($: Engine): Promise<void> {
  tokens = null
  if (platform.secrets === 'keychain') await $.process.run(['/usr/bin/security', 'delete-generic-password', '-s', KEYCHAIN_SERVICE, '-a', KEYCHAIN_ACCOUNT])
  if (platform.secrets === 'libsecret') await $.process.run(['/usr/bin/secret-tool', 'clear', 'service', KEYCHAIN_SERVICE, 'account', KEYCHAIN_ACCOUNT])
  await $.store.set('account', null)
}

async function clientId($: Engine): Promise<string | null> {
  const value = await $.store.get('clientId')
  if (typeof value === 'string' && isClientId(value)) return value
  // Another session may have logged in: its Keychain record carries the id.
  tokens ??= await loadTokens($)

  return tokens?.clientId ?? null
}

async function tokenRequest($: Engine, id: string, params: Record<string, string>): Promise<Tokens | HttpLike> {
  const res = await $.http.fetch(`${API}/2/oauth2/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: formEncode({ ...params, client_id: id }),
  })
  if (!res.ok) return res

  return tokensFrom(JSON.parse(res.text), await $.clock.now(), id)
}

function refreshTokens($: Engine): Promise<Tokens | null> {
  refreshing ??= (async () => {
    // Several sessions share the Keychain record and X rotates the refresh
    // token: take a newer one another session stored before spending ours.
    const stored = await loadTokens($)
    const now = await $.clock.now()
    if (stored && stored.accessToken !== tokens?.accessToken && now < stored.expiresAt - 60_000) {
      tokens = stored

      return stored
    }
    const current = stored ?? tokens
    const id = (await clientId($)) ?? current?.clientId
    if (!id || !current?.refreshToken) return null
    const result = await tokenRequest($, id, { grant_type: 'refresh_token', refresh_token: current.refreshToken })
    if ('status' in result) {
      if (result.status === 400 || result.status === 401) {
        const latest = await loadTokens($)
        if (latest && latest.refreshToken !== current.refreshToken) {
          tokens = latest

          return latest
        }
        await forgetTokens($)
        await setStatus($, { auth: 'signed-out', canPost: false, canLike: false, error: 'ログインの有効期限が切れました。もう一度ログインしてください' })

        return null
      }
      throw new Error(describeApiError(result))
    }
    await saveTokens($, { ...result, scope: result.scope || current.scope })

    return tokens
  })().finally(() => {
    refreshing = null
  })

  return refreshing
}

async function accessToken($: Engine): Promise<string | null> {
  tokens ??= await loadTokens($)
  if (!tokens) return null
  if ((await $.clock.now()) < tokens.expiresAt - 60_000) return tokens.accessToken

  return (await refreshTokens($))?.accessToken ?? null
}

async function apiCall(
  $: Engine,
  method: 'GET' | 'POST' | 'DELETE',
  path: string,
  query: Record<string, string>,
  body?: unknown,
): Promise<HttpLike | null> {
  const qs = formEncode(query)
  const url = `${API}${path}${qs ? `?${qs}` : ''}`
  const send = (token: string) =>
    $.http.fetch(url, {
      method,
      headers: body === undefined ? { Authorization: `Bearer ${token}` } : { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    })
  const token = await accessToken($)
  if (!token) return null
  const res = await send(token)
  if (res.status !== 401) return res
  const renewed = await refreshTokens($)

  return renewed ? send(renewed.accessToken) : null
}

async function account($: Engine): Promise<{ id: string; username: string } | null> {
  const kept = (await $.store.get('account')) as { id?: unknown; username?: unknown } | null
  if (typeof kept?.id === 'string' && typeof kept.username === 'string') return { id: kept.id, username: kept.username }
  const res = await apiCall($, 'GET', '/2/users/me', {})
  if (!res) return null
  if (res.status !== 200) throw new Error(describeApiError(res))
  const me = JSON.parse(res.text)?.data
  if (typeof me?.id !== 'string') throw new Error('アカウント情報を取得できませんでした')
  const found = { id: me.id as string, username: String(me.username) }
  await $.store.set('account', found)

  return found
}

// Fetches one mode's newer posts (or, with `older`, the page past the
// oldest shown); answers the posts that are new to a list already shown.
async function refreshTimeline($: Engine, mode?: Mode, older = false): Promise<Post[]> {
  if ((mode ?? (await readStatus($)).mode) === 'view') {
    if (!older) await reloadView($)

    return []
  }
  if (isFetching) return []
  isFetching = true
  const before = await readStatus($)
  const which = mode ?? before.mode
  await setStatus($, { isLoading: true, error: null })
  try {
    const me = await account($)
    if (!me) {
      await setStatus($, { auth: 'signed-out' })

      return []
    }
    const current = await readList($, which)
    const watched = before.activeTag ? [before.activeTag] : before.tags
    if (which === 'tags' && watched.length === 0) throw new Error('ハッシュタグが登録されていません。`/x tag add #タグ` で登録してください')
    const query: Record<string, string> = {
      // Recent search takes 10 at the least.
      max_results: String(which === 'tags' ? Math.max(10, maxResults) : maxResults),
      'tweet.fields': TWEET_FIELDS,
      expansions: EXPANSIONS,
      'user.fields': USER_FIELDS,
      'media.fields': MEDIA_FIELDS,
    }
    // Bookmarks come in the order they were saved and take no since_id: the
    // first page is read again whole.
    const edge = which === 'bookmarks' ? undefined : older ? current.at(-1) : current[0]
    if (edge) query[older ? 'until_id' : 'since_id'] = edge.id
    if (which === 'tags') query.query = tagQuery(watched)
    const path =
      which === 'home'
        ? `/2/users/${me.id}/timelines/reverse_chronological`
        : which === 'mentions'
          ? `/2/users/${me.id}/mentions`
          : which === 'bookmarks'
            ? `/2/users/${me.id}/bookmarks`
            : '/2/tweets/search/recent'
    const res = await apiCall($, 'GET', path, query)
    if (!res) {
      await setStatus($, { auth: 'signed-out' })

      return []
    }
    if (res.status !== 200) throw new Error(describeApiError(res))
    const fresh = parseTimeline(JSON.parse(res.text))
    await updateList($, which, list => (which === 'bookmarks' ? fresh : older ? mergePosts(list, fresh, KEPT) : mergePosts(fresh, list, KEPT)))
    const s = await readStatus($)
    const isNews = !older && which !== 'bookmarks' && current.length > 0 && fresh.length > 0
    const isShown = s.mode === which
    await setStatus($, {
      auth: 'signed-in',
      account: me.username,
      canPost: canPost(tokens),
      canLike: canLike(tokens),
      fetchedAt: { ...s.fetchedAt, [which]: await $.clock.now() },
      newIds: isShown && !older ? fresh.map(post => post.id) : s.newIds,
      unread: { ...s.unread, [which]: isNews && !isShown ? s.unread[which] + fresh.length : isShown ? 0 : s.unread[which] },
      hasMore: older ? { ...s.hasMore, [which]: fresh.length > 0 } : s.hasMore,
    })

    return isNews ? fresh : []
  } catch (error) {
    await setStatus($, { error: errorText(error) })

    return []
  } finally {
    isFetching = false
    await setStatus($, { isLoading: false })
  }
}

function preview(post: Post): string {
  return `@${post.username}: ${post.text.replace(/\s+/g, ' ').slice(0, 60)}`
}

async function autoTick($: Engine): Promise<void> {
  const freshHome = await refreshTimeline($, 'home')
  const freshMentions = await refreshTimeline($, 'mentions')
  const s = await readStatus($)
  const freshTags = s.mode === 'tags' && s.tags.length > 0 ? await refreshTimeline($, 'tags') : []
  const mention = freshMentions[0]
  if (mention) {
    $.ui.toast(`🔔 X 通知 ${freshMentions.length}件 · ${preview(mention)}`)
  } else if (freshTags[0]) {
    $.ui.toast(`# タグ新着 ${freshTags.length}件 · ${preview(freshTags[0])}`)
  } else if (freshHome[0]) {
    $.ui.toast(`𝕏 新着 ${freshHome.length}件 · ${preview(freshHome[0])}`)
  }
}

async function setAuto($: Engine, minutes: number): Promise<void> {
  autoTimer?.cancel()
  autoTimer = null
  await $.store.set('autoMinutes', minutes)
  await setStatus($, { autoMinutes: minutes })
  const ms = refreshIntervalMs(minutes)
  if (ms > 0 && tokens) autoTimer = $.clock.every(ms, () => void autoTick($))
}

async function switchMode($: Engine, mode: Mode): Promise<void> {
  const s = await readStatus($)
  await setStatus($, { mode, cursor: 0, error: null, notice: null, newIds: [], unread: { ...s.unread, [mode]: 0 } })
  tokens ??= await loadTokens($)
  if ((await readList($, mode)).length === 0 && tokens) await refreshTimeline($, mode)
}

async function loadTags($: Engine): Promise<string[]> {
  const kept = await $.store.get('tags')

  return Array.isArray(kept) ? kept.filter((tag): tag is string => typeof tag === 'string') : []
}

async function saveTags($: Engine, tags: string[]): Promise<void> {
  await $.store.set('tags', tags)
  await setStatus($, { tags })
}

async function showTag($: Engine, tag: string | null): Promise<void> {
  const s = await readStatus($)
  if (s.activeTag !== tag || s.mode !== 'tags') await update($, tagPosts, () => [])
  await setStatus($, { activeTag: tag, hasMore: { ...s.hasMore, tags: true } })
  await switchMode($, 'tags')
}

async function tagCommand($: Engine, rest: string): Promise<string> {
  const [sub = '', ...words] = rest.split(/\s+/).filter(Boolean)
  const tags = await loadTags($)
  const listed = () => (tags.length ? tags.map(tag => `#${tag}`).join(' ') : '（なし）')

  if (sub === 'add' || sub === '追加') {
    const added = words.map(normalizeTag).filter((tag): tag is string => tag !== null)
    if (added.length === 0) return '使い方: `/x tag add #タグ`（複数可）'
    const next = [...tags, ...added.filter(tag => !tags.includes(tag))].slice(0, 20)
    await saveTags($, next)
    await showTag($, null)

    return `登録しました: ${next.map(tag => `#${tag}`).join(' ')}`
  }
  if (sub === 'rm' || sub === 'remove' || sub === '削除') {
    const gone = new Set(words.map(normalizeTag))
    const next = tags.filter(tag => !gone.has(tag))
    await saveTags($, next)
    const s = await readStatus($)
    if (s.activeTag && gone.has(s.activeTag)) await showTag($, null)

    return `登録中: ${next.length ? next.map(tag => `#${tag}`).join(' ') : '（なし）'}`
  }
  if (sub === 'list' || sub === '一覧') return `登録中のハッシュタグ: ${listed()}`

  const single = sub && sub !== 'all' && sub !== 'すべて' ? normalizeTag(sub) : null
  if (sub && sub !== 'all' && sub !== 'すべて' && !single) return '使い方: `/x tag` · `/x tag #タグ` · `/x tag add #タグ` · `/x tag rm #タグ` · `/x tag list`'
  if (!single && tags.length === 0) {
    await setStatus($, { mode: 'tags', activeTag: null, error: null })
    await openPane($)

    return `${tabBar(await readStatus($))}\n\nハッシュタグが登録されていません。\`/x tag add #タグ\` で登録してください`
  }
  await setStatus($, { tags })
  await showTag($, single)
  await openPane($)

  return live($, `${tabBar(await readStatus($))}\n\n${await asText($, 'tags')}`)
}

async function qrCommand($: Engine, rest: string): Promise<string> {
  const [first = '', second = ''] = rest.split(/\s+/)
  const wantsFile = first === 'open' || second === 'open'
  const named = [first, second].find(word => word && word !== 'open')
  let username = named?.replace(/^@/, '') ?? null
  if (username !== null && !/^[A-Za-z0-9_]{1,15}$/.test(username)) return 'ユーザー名の形式が正しくありません（例: `/x qr @example_user`）'
  if (!username) {
    try {
      username = (await account($))?.username ?? null
    } catch (error) {
      return errorText(error)
    }
  }
  if (!username) return '未ログインです。`/x login` でログインするか、`/x qr @ユーザー名` を指定してください'
  const url = `https://x.com/${username}`
  const matrix = encodeQr(url)

  if (wantsFile) {
    const home = await $.env.get('HOME')
    if (!home) return 'ホームフォルダが分かりませんでした'
    const dir = `${platform.cacheRoot ?? (platform.secrets === 'keychain' ? `${home}/Library/Caches` : `${home}/.cache`)}/claude-x-timeline`
    const file = `${dir}/qr-${username}.svg`
    await $.process.run(['/bin/mkdir', '-p', dir])
    await $.fs.write(file, qrSvg(matrix))
    await openUrl($, file)

    return `QRコードの画像を開きました（${url}）`
  }

  await setStatus($, { qrFor: username })
  await openPane($)

  // A surface that draws the row itself shows the code as a picture; this
  // text is what the transcript keeps and what a plain one shows.
  return [`@${username} のQRコード（${url}）`, '```', ...qrRows(matrix, false), '```', '画像で開く: `/x qr open`'].join('\n')
}

async function login($: Engine): Promise<string> {
  const id = await clientId($)
  if (!id) return '先に `/x-timeline client-id <OAuth 2.0 Client ID>` を実行してください'
  // A retry while the listener still waits replaces the PKCE pair and state:
  // only the newest authorization request can complete.
  const pkce = await createPkce()
  pendingLogin = { ...pkce, clientId: id }
  const url = authorizeUrl(id, pkce.challenge, pkce.state)
  await setStatus($, { auth: 'waiting', error: null, authorizeUrl: url })
  if (isLoggingIn) {
    await openUrl($, url)

    return 'ブラウザでXの認可画面を開き直しました'
  }
  isLoggingIn = true

  void (async () => {
    try {
      const listener = $.process.run([platform.python, '-c', CALLBACK_SERVER, String(CALLBACK_PORT)], { timeoutMs: 320_000 })
      await openUrl($, url)
      const done = await listener
      const request = pendingLogin
      if (!request) throw new Error('ログインが取り消されました')
      if (done.exitCode !== 0) {
        throw new Error(
          done.exitCode === 2
            ? '5分以内に認可されませんでした。もう一度ログインしてください'
            : `認可の受け取りに失敗しました（ポート${CALLBACK_PORT}が使用中かもしれません）`,
        )
      }
      const answer = parseQuery(done.stdout.trim())
      if (answer.state !== request.state) throw new Error('認可応答のstateが一致しません。もう一度ログインしてください')
      if (!answer.code) throw new Error(answer.error === 'access_denied' ? '認可がキャンセルされました' : `認可に失敗しました（${answer.error ?? '不明'}）`)
      const result = await tokenRequest($, request.clientId, {
        grant_type: 'authorization_code',
        code: answer.code,
        redirect_uri: REDIRECT_URI,
        code_verifier: request.verifier,
      })
      if ('status' in result) throw new Error(describeApiError(result))
      await $.store.set('account', null)
      await saveTokens($, result)
      await update($, posts, () => [])
      await update($, mentions, () => [])
      await setStatus($, { auth: 'signed-in', authorizeUrl: null, canPost: canPost(result), canLike: canLike(result), newIds: [] })
      $.ui.toast('𝕏 と連携しました')
      await refreshTimeline($)
      await setAuto($, (await readStatus($)).autoMinutes)
    } catch (error) {
      await setStatus($, { auth: tokens ? 'signed-in' : 'signed-out', authorizeUrl: null, error: errorText(error) })
    } finally {
      isLoggingIn = false
      pendingLogin = null
    }
  })()

  return 'ブラウザでXの認可画面を開きました。許可するとタイムラインを取得します'
}

async function logout($: Engine): Promise<string> {
  const id = await clientId($)
  const current = tokens ?? (await loadTokens($))
  if (id && current) {
    for (const [token, hint] of [
      [current.refreshToken, 'refresh_token'],
      [current.accessToken, 'access_token'],
    ] as const) {
      if (!token) continue
      await $.http
        .fetch(`${API}/2/oauth2/revoke`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: formEncode({ token, token_type_hint: hint, client_id: id }),
        })
        .catch(() => undefined)
    }
  }
  autoTimer?.cancel()
  autoTimer = null
  await forgetTokens($)
  await update($, posts, () => [])
  await update($, mentions, () => [])
  await update($, draft, () => EMPTY_DRAFT)
  await setStatus($, { ...INITIAL, auth: 'signed-out', autoMinutes: (await readStatus($)).autoMinutes })

  return 'Xとの連携を解除し、キーチェーンからトークンを削除しました'
}

// `/x p 本文 --image /path.png`: each picture checked before the confirm.
async function checkImages($: Engine, paths: string[]): Promise<string[]> {
  const home = (await $.env.get('HOME')) ?? ''
  const out: string[] = []
  for (const raw of paths.slice(0, 4)) {
    const path = raw.startsWith('~/') ? `${home}${raw.slice(1)}` : raw
    const problem = imagePathProblem(path)
    if (problem) throw new Error(`${raw}: ${problem}`)
    const stat = await $.fs.stat(path).catch(() => null)
    if (stat?.kind !== 'file') throw new Error(`${raw}: ファイルが見つかりません`)
    if (stat.size > IMAGE_LIMIT) throw new Error(`${raw}: 5MB までの画像にしてください`)
    out.push(path)
  }

  return out
}

async function stageDraft($: Engine, text: string, imagePaths: string[] = []): Promise<string> {
  const body = text.trim()
  if (!body && imagePaths.length === 0) return '投稿する文章が空です'
  const before = await readDraft($)
  let images = before.images
  try {
    if (imagePaths.length > 0) images = await checkImages($, imagePaths)
  } catch (error) {
    await setStatus($, { error: errorText(error) })

    return `⚠ ${errorText(error)}`
  }
  const { replyTo, quoteOf } = before
  await update($, draft, () => ({ ...EMPTY_DRAFT, text: body, replyTo, quoteOf, images, isConfirming: true }))
  await setStatus($, { error: null, notice: null })
  const target = replyTo ? `@${replyTo.username} への返信を` : quoteOf ? `@${quoteOf.username} の引用を` : ''
  const attached = images.length ? `\n🖼 画像 ${images.length}枚: ${images.map(path => path.split('/').pop()).join(', ')}` : ''

  return `${target}この内容で投稿しますか？（${weightedLength(body)}/${POST_LIMIT}）\n\n${body}${attached}\n\n確定は「ポストする」か \`/x send\`、取り消しは \`/x cancel\``
}

async function sendDraft($: Engine): Promise<string> {
  const pending = await readDraft($)
  if (!pending.isConfirming || !pending.text) return '確認待ちの投稿はありません'
  if (pending.isPosting) return '投稿中です'
  tokens ??= await loadTokens($)
  if (!canPost(tokens)) {
    const message = '投稿の権限がありません。`/x-timeline login` でログインし直してください'
    await setStatus($, { error: message })

    return message
  }
  if (pending.images.length > 0 && !hasScope(tokens, 'media.write')) {
    const message = '画像の投稿には `/x login` でログインし直してください（画像の許可が増えました）'
    await setStatus($, { error: message })

    return message
  }
  await update($, draft, d => ({ ...EMPTY_DRAFT, ...d, isPosting: true }))
  try {
    const mediaIds: string[] = []
    for (const path of pending.images) mediaIds.push(await uploadImage($, path))
    const body: Record<string, unknown> = { text: pending.text }
    if (pending.replyTo) body.reply = { in_reply_to_tweet_id: pending.replyTo.id }
    if (pending.quoteOf) body.quote_tweet_id = pending.quoteOf.id
    if (mediaIds.length) body.media = { media_ids: mediaIds }
    const res = await apiCall($, 'POST', '/2/tweets', {}, body)
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 201 && res.status !== 200) throw new Error(describeApiError(res))
    const created = JSON.parse(res.text)?.data as { id?: string } | undefined
    const me = await account($)
    let url = ''
    if (created?.id && me) {
      const own: Post = {
        id: created.id,
        text: pending.text,
        createdAt: new Date(await $.clock.now()).toISOString(),
        username: me.username,
        name: me.username,
        likes: 0,
        reposts: 0,
        replies: 0,
        isReply: pending.replyTo !== null,
      }
      url = postUrl(own)
      await update($, posts, list => mergePosts([own], list, KEPT))
    }
    await update($, draft, () => EMPTY_DRAFT)
    await setStatus($, { notice: `投稿しました ${url}`.trim(), error: null })
    $.ui.toast('𝕏 に投稿しました')

    return `投稿しました ${url}`.trim()
  } catch (error) {
    await update($, draft, d => ({ ...EMPTY_DRAFT, ...d, isPosting: false }))
    await setStatus($, { error: errorText(error) })

    return `投稿できませんでした: ${errorText(error)}`
  }
}

// X's media upload, one picture: curl sends the file as a form part and
// reads the Authorization header from stdin, so the token is in no argv.
async function uploadImage($: Engine, path: string): Promise<string> {
  const token = await accessToken($)
  if (!token) throw new Error('ログインが必要です')
  const ext = path.split('.').pop()?.toLowerCase() ?? ''
  const done = await $.process.run(
    ['/usr/bin/curl', '-sS', '--max-time', '60', '--proto', '=https', '-X', 'POST', `${API}/2/media/upload`, '-H', '@-', '-F', `media=@${path};type=${IMAGE_TYPES[ext] ?? 'application/octet-stream'}`, '-F', 'media_category=tweet_image'],
    { stdin: `Authorization: Bearer ${token}\n`, timeoutMs: 70_000 },
  )
  let id: string | undefined
  try {
    const body = JSON.parse(done.stdout)
    id = body?.data?.id ?? body?.media_id_string
  } catch {
    // not JSON
  }
  if (done.exitCode !== 0 || !id) throw new Error(`画像をアップロードできませんでした（${path.split('/').pop()}）${describeApiError({ status: 400, headers: {}, text: done.stdout }).replace(/^X APIエラー 400/, '')}`)

  return id
}

