// A switch on a post the person owns a side of: like, bookmark. The scope it
// needs, its endpoint pair, and the state list that remembers it.
async function togglePostFlag($: Engine, post: Post, flag: 'bookmark'): Promise<void> {
  tokens ??= await loadTokens($)
  if (!hasScope(tokens, 'bookmark.write')) {
    await setStatus($, { error: 'ブックマークには `/x login` でログインし直してください（ブックマークの許可が増えました）' })

    return
  }
  const s = await readStatus($)
  const target = targetOf(post)
  const isOn = s.bookmarked.includes(target) || s.mode === 'bookmarks'
  try {
    const me = await account($)
    if (!me) throw new Error('ログインが必要です')
    const res = isOn
      ? await apiCall($, 'DELETE', `/2/users/${me.id}/bookmarks/${target}`, {})
      : await apiCall($, 'POST', `/2/users/${me.id}/bookmarks`, {}, { tweet_id: target })
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 200) throw new Error(describeApiError(res))
    await setStatus($, { bookmarked: isOn ? s.bookmarked.filter(id => id !== target) : [...s.bookmarked, target], error: null, notice: isOn ? 'ブックマークを外しました' : '🔖 ブックマークしました' })
    if (isOn) await update($, bookmarkPosts, list => list.filter(one => targetOf(one) !== target))
    void flag
  } catch (error) {
    await setStatus($, { error: errorText(error) })
  }
}

async function userIdOf($: Engine, username: string): Promise<{ id: string; username: string }> {
  const s = await readStatus($)
  if (s.view?.kind === 'user' && s.view.profile.username.toLowerCase() === username.toLowerCase()) return { id: s.view.profile.id, username: s.view.profile.username }
  const profile = parseProfile(await apiJson($, `/2/users/by/username/${encodeURIComponent(username)}`, {}))
  if (!profile) throw new Error(`@${username} が見つかりませんでした`)

  return { id: profile.id, username: profile.username }
}

// Follow, unfollow, mute, unmute: one person, by their handle.
async function relate($: Engine, act: 'follow' | 'unfollow' | 'mute' | 'unmute', username: string): Promise<string> {
  tokens ??= await loadTokens($)
  const scope = act === 'follow' || act === 'unfollow' ? 'follows.write' : 'mute.write'
  if (!hasScope(tokens, scope)) return '`/x login` でログインし直してください（フォロー・ミュートの許可が増えました）'
  try {
    const me = await account($)
    if (!me) throw new Error('ログインが必要です')
    const them = await userIdOf($, username.replace(/^@/, ''))
    const res =
      act === 'follow'
        ? await apiCall($, 'POST', `/2/users/${me.id}/following`, {}, { target_user_id: them.id })
        : act === 'unfollow'
          ? await apiCall($, 'DELETE', `/2/users/${me.id}/following/${them.id}`, {})
          : act === 'mute'
            ? await apiCall($, 'POST', `/2/users/${me.id}/muting`, {}, { target_user_id: them.id })
            : await apiCall($, 'DELETE', `/2/users/${me.id}/muting/${them.id}`, {})
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 200) throw new Error(describeApiError(res))
    const s = await readStatus($)
    const without = (list: string[]) => list.filter(id => id !== them.id)
    await setStatus($, {
      followed: act === 'follow' ? [...without(s.followed), them.id] : act === 'unfollow' ? without(s.followed) : s.followed,
      muted: act === 'mute' ? [...without(s.muted), them.id] : act === 'unmute' ? without(s.muted) : s.muted,
      error: null,
    })
    const words = { follow: 'フォローしました', unfollow: 'フォローを解除しました', mute: 'ミュートしました', unmute: 'ミュートを解除しました' }

    return `@${them.username} を${words[act]}`
  } catch (error) {
    await setStatus($, { error: errorText(error) })

    return `⚠ ${errorText(error)}`
  }
}

async function deletePost($: Engine, post: Post): Promise<string> {
  const s = await readStatus($)
  if (post.repostedBy || post.username.toLowerCase() !== (s.account ?? '').toLowerCase()) return '削除できるのは自分のポストだけです'
  try {
    const res = await apiCall($, 'DELETE', `/2/tweets/${post.id}`, {})
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 200) throw new Error(describeApiError(res))
    const gone = (list: Post[]) => list.filter(one => one.id !== post.id)
    await update($, posts, gone)
    await update($, mentions, gone)
    await update($, tagPosts, gone)
    await update($, viewPosts, gone)
    await setStatus($, { deleteAsk: null, notice: 'ポストを削除しました', error: null })

    return 'ポストを削除しました'
  } catch (error) {
    await setStatus($, { deleteAsk: null, error: errorText(error) })

    return `⚠ ${errorText(error)}`
  }
}

