async function toggleLike($: Engine, post: Post): Promise<void> {
  tokens ??= await loadTokens($)
  if (!canLike(tokens)) {
    await setStatus($, { error: 'いいねの権限がありません。`/x-timeline login` でログインし直してください' })

    return
  }
  const s = await readStatus($)
  const target = targetOf(post)
  const isLiked = s.liked.includes(target)
  try {
    const me = await account($)
    if (!me) throw new Error('ログインが必要です')
    const res = isLiked
      ? await apiCall($, 'DELETE', `/2/users/${me.id}/likes/${target}`, {})
      : await apiCall($, 'POST', `/2/users/${me.id}/likes`, {}, { tweet_id: target })
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 200) throw new Error(describeApiError(res))
    const liked = isLiked ? s.liked.filter(id => id !== target) : [...s.liked, target]
    const delta = isLiked ? -1 : 1
    await setStatus($, { liked, error: null })
    const bump = (list: Post[]) => list.map(one => (targetOf(one) === target ? { ...one, likes: Math.max(0, (one.likes ?? 0) + delta) } : one))
    await update($, posts, bump)
    await update($, mentions, bump)
    await update($, tagPosts, bump)
  } catch (error) {
    await setStatus($, { error: errorText(error) })
  }
}

// A repost shares the post with the person's followers, so the first press
// asks and the second confirms, as X's own menu does.
async function toggleRepost($: Engine, post: Post, isConfirmed: boolean): Promise<void> {
  const s = await readStatus($)
  const target = targetOf(post)
  const isReposted = s.reposted.includes(target)
  if (!isReposted && !isConfirmed) {
    await setStatus($, { repostAsk: s.repostAsk === post.id ? null : post.id })

    return
  }
  tokens ??= await loadTokens($)
  if (!canPost(tokens)) {
    await setStatus($, { repostAsk: null, error: 'リポストの権限がありません。`/x login` でログインし直してください' })

    return
  }
  try {
    const me = await account($)
    if (!me) throw new Error('ログインが必要です')
    const res = isReposted
      ? await apiCall($, 'DELETE', `/2/users/${me.id}/retweets/${target}`, {})
      : await apiCall($, 'POST', `/2/users/${me.id}/retweets`, {}, { tweet_id: target })
    if (!res) throw new Error('ログインが必要です')
    if (res.status !== 200) throw new Error(describeApiError(res))
    const reposted = isReposted ? s.reposted.filter(id => id !== target) : [...s.reposted, target]
    const delta = isReposted ? -1 : 1
    await setStatus($, { reposted, repostAsk: null, error: null })
    const bump = (list: Post[]) => list.map(one => (targetOf(one) === target ? { ...one, reposts: Math.max(0, (one.reposts ?? 0) + delta) } : one))
    await update($, posts, bump)
    await update($, mentions, bump)
    await update($, tagPosts, bump)
  } catch (error) {
    await setStatus($, { repostAsk: null, error: errorText(error) })
  }
}

const POST_QUERY = { 'tweet.fields': TWEET_FIELDS, expansions: EXPANSIONS, 'user.fields': USER_FIELDS, 'media.fields': MEDIA_FIELDS }

async function apiJson($: Engine, path: string, query: Record<string, string>): Promise<unknown> {
  const res = await apiCall($, 'GET', path, query)
  if (!res) throw new Error('ログインが必要です。`/x login` でログインしてください')
  if (res.status !== 200) throw new Error(describeApiError(res))

  return JSON.parse(res.text)
}

// A thread: the conversation's first post, then its replies oldest first.
// Recent search reaches the last 7 days, as X's own API allows.
async function loadThread($: Engine, from: Post | string): Promise<{ view: View; list: Post[] }> {
  // A listed post already knows its conversation; an id alone is looked up.
  const postId = typeof from === 'string' ? from : targetOf(from)
  const [post] = typeof from !== 'string' && from.conversationId ? [from] : parseSingle(await apiJson($, `/2/tweets/${postId}`, POST_QUERY))
  if (!post) throw new Error('ポストが見つかりませんでした')
  const rootId = post.conversationId ?? postId
  const [root] = rootId === postId ? [post] : parseSingle(await apiJson($, `/2/tweets/${rootId}`, POST_QUERY).catch(() => ({})))
  const found = await apiJson($, '/2/tweets/search/recent', {
    ...POST_QUERY,
    query: `conversation_id:${rootId}`,
    max_results: String(Math.max(10, maxResults)),
  })
  const replies = parseTimeline(found).reverse()

  return { view: { kind: 'thread', rootId, username: (root ?? post).username }, list: mergePosts([...(root ? [root] : []), ...(root ? [] : [post]), ...replies], [], KEPT) }
}

async function loadUser($: Engine, username: string): Promise<{ view: View; list: Post[] }> {
  const profile = parseProfile(await apiJson($, `/2/users/by/username/${encodeURIComponent(username)}`, { 'user.fields': PROFILE_FIELDS }))
  if (!profile) throw new Error(`@${username} が見つかりませんでした`)
  const list = parseTimeline(await apiJson($, `/2/users/${profile.id}/tweets`, { ...POST_QUERY, max_results: String(Math.max(5, maxResults)) }))

  return { view: { kind: 'user', profile }, list }
}

async function loadSearch($: Engine, query: string): Promise<{ view: View; list: Post[] }> {
