async function loadList($: Engine, listId: string, name: string): Promise<{ view: View; list: Post[] }> {
  const list = parseTimeline(await apiJson($, `/2/lists/${listId}/tweets`, { ...POST_QUERY, max_results: String(Math.max(5, maxResults)) }))

