}

async function loadLists($: Engine): Promise<{ view: View; list: Post[] }> {
  tokens ??= await loadTokens($)
  if (!hasScope(tokens, 'list.read')) throw new Error('リストには `/x login` でログインし直してください（リストの許可が増えました）')
  const me = await account($)
  if (!me) throw new Error('ログインが必要です')
  const fields = { 'list.fields': 'member_count,private,description', max_results: '100' }
  const owned = parseLists(await apiJson($, `/2/users/${me.id}/owned_lists`, fields))
  const followed = parseLists(await apiJson($, `/2/users/${me.id}/followed_lists`, fields).catch(() => ({})))
  const lists = [...owned, ...followed.filter(one => !owned.some(mine => mine.id === one.id))]

  return { view: { kind: 'lists', lists }, list: [] }
}

async function loadTrends($: Engine): Promise<{ view: View; list: Post[] }> {
  const trends = parseTrends(await apiJson($, '/2/users/personalized_trends', { 'personalized_trend.fields': 'category,post_count,trend_name,trending_since' }))

  return { view: { kind: 'trends', trends }, list: [] }
}

function loaderFor($: Engine, view: View): Promise<{ view: View; list: Post[] }> {
  if (view.kind === 'thread') return loadThread($, view.rootId)
  if (view.kind === 'user') return loadUser($, view.profile.username)
  if (view.kind === 'search') return loadSearch($, view.query)
  if (view.kind === 'likes') return loadLikes($, view.username)
  if (view.kind === 'list') return loadList($, view.listId, view.name)

  return view.kind === 'lists' ? loadLists($) : loadTrends($)
}

let isLoadingView = false

async function showView($: Engine, load: Promise<{ view: View; list: Post[] }>): Promise<string> {
  const before = await readStatus($)
  await setStatus($, { isLoading: true, error: null, notice: null, backTo: before.mode === 'view' ? before.backTo : before.mode })
  try {
    const { view, list } = await load
    await update($, viewPosts, () => list)
    await setStatus($, { mode: 'view', view, cursor: 0, newIds: [], fetchedAt: { ...before.fetchedAt, view: await $.clock.now() } })
  } catch (error) {
    await setStatus($, { error: errorText(error) })
  } finally {
    await setStatus($, { isLoading: false })
  }
  await openPane($)
  const after = await readStatus($)
  if (after.mode !== 'view') return `⚠ ${after.error ?? '表示できませんでした'}`

  return live($, `${tabBar(after)}\n\n${await asText($, 'view')}`)
}

async function reloadView($: Engine): Promise<void> {
  const view = (await readStatus($)).view
  if (!view || isLoadingView) return
  isLoadingView = true
  try {
    await showView($, loaderFor($, view))
  } finally {
    isLoadingView = false
  }
}

async function goBack($: Engine): Promise<string> {
  const s = await readStatus($)

  return showMode($, s.mode === 'view' ? s.backTo : s.mode)
}

function viewTitle(view: View | null): string {
  if (!view) return ''
  if (view.kind === 'thread') return `💭 @${view.username} のスレッド`
  if (view.kind === 'user') return `👤 @${view.profile.username}`
  if (view.kind === 'search') return `🔍 ${view.query}`
  if (view.kind === 'likes') return `♡ @${view.username} のいいね`
  if (view.kind === 'list') return `📋 ${view.name}`

  return view.kind === 'lists' ? '📋 リスト' : '📈 トレンド'
}

// The view's own lines in the chat: what is not a post (lists, trends).
function viewIndexText(view: View): string | null {
  if (view.kind === 'lists') {
    return view.lists.length
      ? view.lists.map((list, i) => `\`${i + 1}\` **${list.name}**${list.isPrivate ? ' 🔒' : ''}${list.members !== null ? ` · ${list.members}人` : ''}${list.description ? `  \n<sub>${list.description}</sub>` : ''}`).join('\n\n') + '\n\n<sub>開く: `/x list 番号`</sub>'
      : 'リストがありません'
  }
  if (view.kind === 'trends') {
    return view.trends.length
      ? view.trends.map((trend, i) => `\`${i + 1}\` **${trend.name}**${trend.posts ? ` · ${compactCount(trend.posts)}件のポスト` : ''}${trend.category ? ` · ${trend.category}` : ''}`).join('  \n') + '\n\n<sub>検索: `/x trend 番号`</sub>'
      : 'トレンドを取得できませんでした'
  }

  return null
}

async function asText($: Engine, mode: Mode): Promise<string> {
  let list = await readList($, mode)
  // A view is loaded by its own command; an empty one (no results) stays so.
  if (list.length === 0 && mode !== 'view') {
    await refreshTimeline($, mode)
    list = await readList($, mode)
  }
  const s = await readStatus($)
  if (s.error) return `⚠ ${s.error}`
  const index = mode === 'view' && s.view ? viewIndexText(s.view) : null
  if (index !== null) return `_${viewTitle(s.view)}_\n\n${index}`
  if (list.length === 0 && mode === 'view') return `_${viewTitle(s.view)}_\n\n見つかりませんでした`
  if (list.length === 0) return s.auth === 'signed-in' ? '表示できるポストがありません' : '未ログインです。`/x-timeline login` でログインしてください'
  const now = await $.clock.now()
  const tagLabel = s.activeTag ? `#${s.activeTag}` : s.tags.map(tag => `#${tag}`).join(' ')
  const fetchedAt = s.fetchedAt[mode]
  const when = fetchedAt ? ` · ${relativeTime(new Date(fetchedAt).toISOString(), now)}前に更新` : ''
  const view = mode === 'view' ? s.view : null
  const heading = view
    ? view.kind === 'user'
      ? `${profileText(view.profile)}\n\n_@${view.profile.username} の最新ポスト${when}_`
      : view.kind === 'thread'
        ? `_💭 @${view.username} のポストのスレッド（返信は古い順・直近7日）${when}_`
        : `_${viewTitle(view)}${when}_`
    : mode === 'bookmarks'
      ? `_🔖 @${s.account ?? ''} のブックマーク${when}_`
      : mode === 'home'
      ? `_@${s.account ?? ''} のホーム${when}_`
      : mode === 'mentions'
        ? `_@${s.account ?? ''} へのメンション${when}_`
        : `_${tagLabel} の最新ポスト${when}_`

  const page = list.slice(0, SHOWN_AS_TEXT)
  // The numbers the chat's actions (`/x like 3`) refer to.
  await setStatus($, { shown: { ...s.shown, [mode]: page.map(post => post.id) } })

  return [heading, ...page.map((post, i) => postText(post, now, i + 1))].join('\n\n---\n\n')
}

function displayWidth(text: string): number {
  let width = 0
  for (const char of text) width += (char.codePointAt(0) ?? 0) > 0x2e80 ? 2 : 1

  return width
}

type TextElement = (props: Record<string, unknown>, ...children: unknown[]) => unknown

// A round avatar stand-in: the name's first letter on a color the handle picks.
function avatar(Text: unknown, name: string, username: string) {
  const T = Text as TextElement
  let hash = 0
  for (const char of username) hash = (hash * 31 + (char.codePointAt(0) ?? 0)) >>> 0
  const color = AVATAR_COLORS[hash % AVATAR_COLORS.length] ?? ACCENT
  const initial = [...(name.trim() || username || '?')][0] ?? '?'
  const cell = displayWidth(initial) > 1 ? ` ${initial}` : ` ${initial.toUpperCase()} `

  return h(T as never, { color: '#ffffff', backgroundColor: color, bold: true }, cell)
}

// Post text with #tags, @mentions and links in X's blue.
function richText(Text: unknown, text: string, links?: Post['links']) {
  const T = Text as TextElement

  return segments(text, links).map(part => (part.kind === 'text' ? part.text : h(T as never, { color: ACCENT }, part.text)))
}

async function ensureMediaDir($: Engine): Promise<string | null> {
  if (mediaDir) return mediaDir
  const home = await $.env.get('HOME')
  if (!home) return null
  const dir = `${platform.cacheRoot ?? (platform.secrets === 'keychain' ? `${home}/Library/Caches` : `${home}/.cache`)}/claude-x-timeline/media`
  await $.process.run(['/bin/mkdir', '-p', dir])
  mediaDir = dir

  return dir
}

// Fetches the small PNG of each picture the pane shows, from X's image host
// only; the terminal draws the file, so no pixel crosses `$`.
async function prefetchImages($: Engine, list: Post[]): Promise<void> {
  const dir = await ensureMediaDir($)
  if (!dir) return
  const ready = new Set((await readStatus($)).imagesReady)
  const wanted = list
    .slice(0, 12)
    .flatMap(post => (post.images ?? []).slice(0, 2))
    .filter(image => /^[A-Za-z0-9_]+$/.test(image.key) && isMediaUrl(image.url) && !ready.has(image.key) && !mediaInFlight.has(image.key))
  for (const image of wanted) {
    mediaInFlight.add(image.key)
    const done = await $.process
      .run(['/usr/bin/curl', '-sSfL', '--max-time', '15', '--proto', '=https', '-o', `${dir}/${image.key}.png`, mediaVariant(image.url, 'png', 'small')], { timeoutMs: 20_000 })
      .catch(() => null)
    mediaInFlight.delete(image.key)
    if (done?.exitCode === 0) await update($, status, s => ({ ...INITIAL, ...s, imagesReady: [...(s.imagesReady ?? []), image.key].slice(-300) }))
  }
}

async function selected($: Engine): Promise<Post | undefined> {
  const s = await readStatus($)
  const list = await readList($, s.mode)

  return list[Math.min(s.cursor, list.length - 1)]
}

async function moveCursor($: Engine, delta: number): Promise<void> {
  const s = await readStatus($)
  const length = (await readList($, s.mode)).length
  await setStatus($, { cursor: Math.max(0, Math.min(length - 1, s.cursor + delta)), repostAsk: null })
}

async function onSelected($: Engine, act: 'like' | 'repost' | 'reply' | 'open' | 'user' | 'thread' | 'bookmark' | 'quote'): Promise<void> {
  const post = await selected($)
  if (!post) return
  if (act === 'bookmark') return togglePostFlag($, post, 'bookmark')
  if (act === 'quote') return startQuote($, post)
  if (act === 'like') return toggleLike($, post)
  if (act === 'repost') return toggleRepost($, post, (await readStatus($)).reposted.includes(targetOf(post)))
  if (act === 'reply') return startReply($, post)
  if (act === 'open') {
    await openUrl($, postUrl(post))

    return
  }
  await showView($, act === 'user' ? loadUser($, post.username) : loadThread($, post))
}

async function showMore($: Engine, site: 'pane' | 'chat', total: number, shown: number): Promise<void> {
  const s = await readStatus($)
  if (site === 'chat') await setStatus($, { chatLimit: s.chatLimit + 10 })
  if (site === 'pane' || total <= shown + 10) await refreshTimeline($, s.mode, true)
}

// Marks a listing as the chat's live one: its row draws as the timeline.
async function live($: Engine, text: string): Promise<string> {
  await setStatus($, { liveTail: text.slice(-200), chatLimit: 10 })

  return text
}

async function openPane($: Engine): Promise<boolean> {
  const opened = await $.ui.open({ id: PANE, title: TITLE })

  return opened.isPlaced
}

