const TAB_LABELS: Record<Mode, string> = { home: '𝕏 ホーム', mentions: '🔔 通知', tags: '# タグ', bookmarks: '🔖 ブックマーク', view: '表示中' }
const TAB_ORDER: Mode[] = ['home', 'mentions', 'tags', 'bookmarks']

// The tab row a text answer starts with: the one shown in bold, the others
// with their unread count, and how to switch.
function tabBar(s: Status): string {
  const tabs = TAB_ORDER.map((mode, i) => {
    const label = `${i + 1} ${TAB_LABELS[mode]}`
    const unread = s.unread[mode] > 0 && mode !== s.mode ? ` 🔵${s.unread[mode]}` : ''

    return mode === s.mode ? `**${label}**` : `${label}${unread}`
  })
  const current = s.mode === 'view' && s.view ? `　›　**${viewTitle(s.view)}**（\`/x back\` で戻る）` : ''

  return `${tabs.join('　·　')}${current}  \n<sub>\`/x 1\`〜\`/x 4\` タブ · \`/x r\` 更新 · \`/x like 2\` いいね · \`/x thread 2\` スレッド · 💬🔁♡ を押すとXの画面で操作 · \`/x help\`</sub>`
}

// Every switch answers in the transcript too: a surface may seat no pane,
// or the person may be reading the conversation rather than the pane.
async function showMode($: Engine, mode: Mode): Promise<string> {
  const before = await readStatus($)
  await switchMode($, mode)
  const hasPosts = (await readList($, mode)).length > 0
  const canFetch = mode !== 'tags' || before.tags.length > 0 || before.activeTag !== null
  if (hasPosts && canFetch && before.auth === 'signed-in') await refreshTimeline($, mode)
  await openPane($)
  const body = await asText($, mode)

  return live($, `${tabBar(await readStatus($))}\n\n${body}`)
}

async function nextTab($: Engine): Promise<string> {
  const s = await readStatus($)
  // A tab with nothing to show, or one the login lacks the scope for, is skipped.
  tokens ??= await loadTokens($)
  const order = TAB_ORDER.filter(mode => (mode !== 'tags' || s.tags.length > 0) && (mode !== 'bookmarks' || hasScope(tokens, 'bookmark.read')))
  const next = order[(order.indexOf(s.mode) + 1) % order.length] ?? 'home'

  return showMode($, next)
}

async function postByNumber($: Engine, word: string): Promise<Post | undefined> {
  const s = await readStatus($)
  const id = s.shown[s.mode][Number(word) - 1]

  return id ? (await readList($, s.mode)).find(one => one.id === id) : undefined
}

async function viewCommand($: Engine, verb: string, rest: string): Promise<string> {
  const [first = ''] = rest.split(/\s+/)
  if (verb === 'list' || verb === 'trend') {
    const view = (await readStatus($)).view
    const index = Number(first) - 1
    if (verb === 'list') {
      const list = view?.kind === 'lists' ? view.lists[index] : undefined
      if (/^\d{5,}$/.test(first)) return showView($, loadList($, first, `リスト ${first}`))

      return list ? showView($, loadList($, list.id, list.name)) : '先に `/x lists` でリストを表示してから `/x list 番号` で開いてください'
    }
    const trend = view?.kind === 'trends' ? view.trends[index] : undefined

    return trend ? showView($, loadSearch($, trend.name)) : '先に `/x trends` でトレンドを表示してから `/x trend 番号` で検索してください'
  }
  if (verb === 'user' && /^@?[A-Za-z0-9_]{1,15}$/.test(first) && !/^\d+$/.test(first)) return showView($, loadUser($, first.replace(/^@/, '')))
  const post = await postByNumber($, first)
  if (!post) return verb === 'thread' ? '使い方: `/x thread 番号`（番号はチャットに表示中のポスト）' : '使い方: `/x user @ユーザー名` または `/x user 番号`'

  return verb === 'thread' ? showView($, loadThread($, post)) : showView($, loadUser($, post.username))
}

// Acts on a post the chat listed, by the number it was shown under.
async function postAction($: Engine, verb: string, rest: string, originKind: string): Promise<string> {
  const [first = '', ...words] = rest.split(/\s+/)
  const s = await readStatus($)
  const id = s.shown[s.mode][Number(first) - 1]
  const post = id ? (await readList($, s.mode)).find(one => one.id === id) : undefined
  if (!post) return `番号を指定してください（例: \`/x ${verb === 'open-post' ? 'open' : verb === 'repost' ? 'rt' : verb} 3\`）。番号はチャットに表示中のポストのものです`
  const who = `@${post.username}「${post.text.replace(/\s+/g, ' ').slice(0, 30)}」`

  if (verb === 'open-post') {
    await openUrl($, postUrl(post))

    return `${who} をブラウザで開きました`
  }
  if (verb === 'reply') {
    await startReply($, post)
    const body = words.join(' ')

    return body ? stageDraft($, body) : `${who} への返信を書いています。\`/x reply ${first} 本文\` で確認画面に進みます`
  }
  if (verb === 'quote') {
    await startQuote($, post)
    const body = words.join(' ')

    return body ? stageDraft($, body) : `${who} を引用します。\`/x quote ${first} 本文\` で確認画面に進みます`
  }
  if (!PERSON_ORIGINS.includes(originKind)) return 'いいね・リポスト・ブックマーク・削除はご本人の操作でのみ行えます'
  if (verb === 'bookmark') {
    await togglePostFlag($, post, 'bookmark')
    const after = await readStatus($)

    return after.error ? `⚠ ${after.error}` : `${after.notice ?? ''} ${who}`.trim()
  }
  if (verb === 'delete') {
    if (post.repostedBy || post.username.toLowerCase() !== (s.account ?? '').toLowerCase()) return '削除できるのは自分のポストだけです'
    if (words[0] !== 'yes' && words[0] !== 'はい') return `🗑 ${who} を削除しますか？ 取り消せません。実行は \`/x delete ${first} yes\``

    return deletePost($, post)
  }
  if (verb === 'like') {
    const wasLiked = s.liked.includes(targetOf(post))
    await toggleLike($, post)
    const after = await readStatus($)
    if (after.error) return `⚠ ${after.error}`

    return wasLiked ? `${who} のいいねを取り消しました` : `♥ ${who} にいいねしました`
  }
  const isReposted = s.reposted.includes(targetOf(post))
  if (!isReposted && words[0] !== 'yes' && words[0] !== 'はい') {
    return `🔁 ${who} をリポストしますか？ 実行は \`/x rt ${first} yes\``
  }
  await toggleRepost($, post, true)
  const after = await readStatus($)
  if (after.error) return `⚠ ${after.error}`

  return isReposted ? `${who} のリポストを取り消しました` : `🔁 ${who} をリポストしました`
}

async function runCommand($: Engine, raw: string, originKind: string, isShort: boolean): Promise<string> {
  const args = raw.trim()
  const [word = ''] = args.split(/\s+/)
  const rest = args.slice(word.length).trim()
  const verb = word === '' ? (isShort ? 'toggle' : 'open') : (VERBS[word.toLowerCase()] ?? VERBS[word] ?? 'help')

  switch (verb) {
    case 'open':
      return showMode($, (await readStatus($)).mode)
    case 'toggle':
      return nextTab($)
    case 'home':
    case 'mentions':
    case 'bookmarks':
      if (verb === 'bookmarks' && !hasScope((tokens ??= await loadTokens($)), 'bookmark.read')) return 'ブックマークには `/x login` でログインし直してください（ブックマークの許可が増えました）'

      return showMode($, verb)
    case 'search':
      if (!rest) return '使い方: `/x search 検索する言葉`（X の検索演算子も使えます。直近7日分）'

      return showView($, loadSearch($, rest))
    case 'trends':
      return showView($, loadTrends($))
    case 'lists':
      return showView($, loadLists($))
    case 'likes':
      return showView($, loadLikes($, rest ? rest.replace(/^@/, '') : null))
    case 'list':
    case 'trend':
      return viewCommand($, verb, rest)
    case 'follow':
    case 'unfollow':
    case 'mute':
    case 'unmute':
      if (!PERSON_ORIGINS.includes(originKind)) return 'フォロー・ミュートはご本人の操作でのみ行えます'
      if (!/^@?[A-Za-z0-9_]{1,15}$/.test(rest)) return `使い方: \`/x ${verb} @ユーザー名\``

      return relate($, verb, rest)
    case 'bookmark':
    case 'quote':
    case 'delete':
      return postAction($, verb, rest, originKind)
    case 'tag':
      return tagCommand($, rest)
    case 'like':
    case 'repost':
    case 'reply':
    case 'open-post':
      return postAction($, verb, rest, originKind)
    case 'back':
      return goBack($)
    case 'thread':
    case 'user':
      return viewCommand($, verb, rest)
    case 'qr':
      return qrCommand($, rest)
    case 'login':
      await openPane($)

      return login($)
    case 'logout':
      return logout($)
    case 'refresh':
      void refreshTimeline($)

      return '⟳ 更新しています'
    case 'auto': {
      const minutes = rest === '' ? ((await readStatus($)).autoMinutes > 0 ? 0 : 5) : rest === 'off' ? 0 : Number(rest)
      if (!Number.isFinite(minutes) || minutes < 0) return '使い方: `/x a 5`（分）・`/x a off` で停止（最短5分）'
      const step = minutes === 0 ? 0 : Math.max(5, minutes)
      await setAuto($, step)

      return step === 0 ? '⏱ 自動更新を止めました' : `⏱ ${step}分ごとにホームと通知を更新し、新着をトーストでお知らせします`
    }
    case 'post': {
      await openPane($)
      const { text, images } = parsePostArgs(rest)

      return stageDraft($, text, images)
    }
    case 'post-send':
      if (!PERSON_ORIGINS.includes(originKind)) return '投稿の確定はご本人の操作でのみ行えます'

      return sendDraft($)
    case 'post-cancel':
      return cancelDraft($)
    case 'client-id': {
      const { id, alsoLogin } = parseClientIdArgs(rest)
      if (!id) return 'Client IDの形式が正しくありません（Developer Consoleの「OAuth 2.0 Client ID」）'
      await $.store.set('clientId', id)
      if (alsoLogin) return `Client IDを保存しました。${await login($)}`

      return 'Client IDを保存しました。`/x login` でログインしてください'
    }
    default:
      return USAGE
  }
}

// The profile code as a picture: an SVG where the surface draws one (the
// desktop, an editor, the phone), half blocks black on white on a terminal.
function qrCard(elements: unknown, surface: string, username: string) {
  const table = elements as Record<string, TextElement | undefined>
  const T = table.Text as TextElement
  const url = `https://x.com/${username}`
  const matrix = encodeQr(url)
  const Svg = surface !== 'terminal' ? table.Svg : undefined
  const picture = Svg
    ? [h(Svg as never, { source: qrSvg(matrix, 4, 8), alt: `${url} のQRコード`, width: 240, height: 240 })]
    : qrRows(matrix, true).map(row => h(T as never, { color: '#000000', backgroundColor: '#ffffff' }, row))

  return [h(T as never, { bold: true }, `@${username}`), ...picture, h(T as never, { dimColor: true }, `x.com/${username}`)]
}

async function drawTimeline($: Engine, e: RenderInput<'Pane' | 'CommandOutput'>, columns: number, site: 'pane' | 'chat') {
  const elements = $.ui.resolve(e)
  const { Box, Text, Button, Link } = elements
  const Input = 'Input' in elements ? elements.Input : undefined
  // Pictures draw on a terminal only (kitty graphics, the alt elsewhere).
  const Image = e.surface === 'terminal' && 'Image' in elements ? elements.Image : undefined
  const s = await readStatus($)
  const all: Post[] = await readList($, s.mode)
  // The chat's live row shows a page of the list; the pane scrolls it whole.
  const list = site === 'chat' ? all.slice(0, s.chatLimit) : all
  const pending = await readDraft($)
  const now = await $.clock.now()
  const hasClientId = (await clientId($)) !== null
  const isSignedIn = s.auth === 'signed-in'
  const fetchedAt = s.fetchedAt[s.mode]
  const nextAuto = AUTO_STEPS[(AUTO_STEPS.indexOf(s.autoMinutes) + 1) % AUTO_STEPS.length] ?? 0
  const rule = '─'.repeat(Math.max(8, Math.min(columns, 100)))
  const isNew = new Set(s.newIds)
  const liked = new Set(s.liked)
  const length = weightedLength(pending.text)
  const cursor = Math.min(s.cursor, Math.max(0, list.length - 1))
  const profileName = s.view?.kind === 'user' ? s.view.profile.username : ''
  const ready = new Set(s.imagesReady)
  // A terminal that draws pictures gets them fetched as the pane shows them.
  if (Image && list.slice(0, 12).some(post => (post.images ?? []).slice(0, 2).some(image => !ready.has(image.key) && !mediaInFlight.has(image.key)))) {
    void prefetchImages($, list)
  }
  const imageColumns = Math.max(16, Math.min(48, columns - 8))
  const imageRows = (image: { width: number; height: number }) =>
    Math.max(4, Math.min(18, Math.round(image.width > 0 && image.height > 0 ? (imageColumns * image.height) / image.width / 2 : imageColumns / 3)))

  const tab = (mode: Mode, label: string, hotkey: string) => {
    const isActive = s.mode === mode
    const count = s.unread[mode]

    return (
      <Button key={`mode-${mode}`} plain hotkey={hotkey} onPress={() => switchMode($, mode)}>
        <Text bold={isActive} color={isActive ? ACCENT : undefined} dimColor={!isActive} underline={isActive}>
          {label}
        </Text>
        {count > 0 && <Text color={ACCENT}> ●{count}</Text>}
      </Button>
    )
  }

  const meta = [
    s.account ? `@${s.account}` : null,
    s.isLoading ? '⟳ 更新中' : fetchedAt ? `${relativeTime(new Date(fetchedAt).toISOString(), now)}前に更新` : null,
    s.autoMinutes > 0 ? `自動 ${s.autoMinutes}分` : null,
  ]
    .filter(Boolean)
    .join(' · ')

  if (!isSignedIn) {
    return (
      <Box flexDirection="column" gap={1}>
        <Text>
          <Text bold color={ACCENT}>
            𝕏
          </Text>
          <Text dimColor> タイムライン</Text>
        </Text>
        {s.error && <Text color="error">⚠ {s.error}</Text>}
        {s.auth === 'waiting' ? (
          <Box flexDirection="column">
            <Text>ブラウザでXの認可を待っています…</Text>
            {s.authorizeUrl && <Link href={s.authorizeUrl} label="ブラウザが開かない場合はここから認可" />}
          </Box>
        ) : hasClientId ? (
          <Box flexDirection="column" gap={1}>
            <Text dimColor>Xアカウントと連携すると、ホーム・通知・投稿がここで使えます。</Text>
            <Button key="login" label="𝕏 でログイン" hotkey="l" onPress={() => login($)} />
          </Box>
        ) : (
          <Box flexDirection="column">
            <Text>はじめに</Text>
            <Text dimColor>1. X Developer Console でネイティブアプリを作成</Text>
            <Text dimColor>2. コールバックURIに {REDIRECT_URI} を登録</Text>
            <Text dimColor>3. `/x-timeline client-id {'<Client ID>'}` → `/x-timeline login`</Text>
          </Box>
        )}
        {s.auth === 'unknown' && <Button key="refresh" label="再読み込み" hotkey="r" onPress={() => void refreshTimeline($)} />}
      </Box>
    )
  }

  const me = s.account ?? ''
  const tabColumn = (mode: Mode, label: string, hotkey: string) => {
    const isActive = s.mode === mode
    const count = s.unread[mode]
    const width = displayWidth(`${hotkey}: ${label}`) + (count > 0 ? 3 + String(count).length : 0)

    return (
      <Box flexDirection="column">
        <Button key={`mode-${mode}`} plain hotkey={hotkey} onPress={() => switchMode($, mode)}>
          <Text bold={isActive} dimColor={!isActive}>
            {label}
          </Text>
          {count > 0 && <Text color={ACCENT}> ● {count}</Text>}
        </Button>
        <Text color={isActive ? ACCENT : 'subtle'}>{(isActive ? '━' : ' ').repeat(width)}</Text>
      </Box>
    )
  }
  const count = (n: number | undefined) => compactCount(n ?? 0)

  return (
    <Box flexDirection="column">
      <Box justifyContent="space-between" flexWrap="wrap" columnGap={2}>
        <Text>
          <Text bold>𝕏</Text>
          <Text bold> {TAB_LABELS[s.mode].replace(/^\S+ /, '')}</Text>
        </Text>
        <Text dimColor>{meta}</Text>
      </Box>
      <Box columnGap={3} marginTop={1}>
        {tabColumn('home', 'ホーム', '1')}
        {tabColumn('mentions', '通知', '2')}
        {tabColumn('tags', '# タグ', '3')}
        {tabColumn('bookmarks', '🔖', '4')}
      </Box>
      <Text color="subtle">{rule}</Text>

      {s.mode === 'view' && s.view && (
        <Box flexDirection="column">
          <Box columnGap={2}>
            <Button key="back" label="← 戻る" hotkey="h" plain onPress={() => void goBack($)} />
            <Text bold>{viewTitle(s.view)}</Text>
          </Box>
          {s.view.kind === 'user' && (
            <Box flexDirection="column" marginTop={1}>
              <Box columnGap={1}>
                {avatar(Text, s.view.profile.name, s.view.profile.username)}
                <Text>
                  <Text bold>{s.view.profile.name}</Text>
                  {s.view.profile.isVerified && <Text color={ACCENT}> ☑</Text>}
                  <Text dimColor> @{s.view.profile.username}</Text>
                </Text>
              </Box>
              {s.view.profile.description && <Text>{richText(Text, s.view.profile.description)}</Text>}
              {(s.view.profile.location || s.view.profile.url || s.view.profile.joined) && (
                <Text dimColor>
                  {[
                    s.view.profile.location ? `📍 ${s.view.profile.location}` : '',
                    s.view.profile.url ? `🔗 ${s.view.profile.url.replace(/^https?:\/\//, '')}` : '',
                    joinedText(s.view.profile.joined) ? `📅 ${joinedText(s.view.profile.joined)}` : '',
                  ]
                    .filter(Boolean)
                    .join('　')}
                </Text>
              )}
              <Text>
                <Text bold>{compactCount(s.view.profile.following)}</Text>
                <Text dimColor> フォロー中　</Text>
                <Text bold>{compactCount(s.view.profile.followers)}</Text>
                <Text dimColor> フォロワー　</Text>
                <Text bold>{compactCount(s.view.profile.posts)}</Text>
                <Text dimColor> ポスト</Text>
              </Text>
            </Box>
          )}
          {s.view.kind === 'user' && (
            <Box columnGap={2} marginTop={1}>
              {s.followed.includes(s.view.profile.id) ? (
                <Button key="unfollow" label="フォロー中 ✓（解除）" plain onPress={() => void relate($, 'unfollow', profileName)} />
              ) : (
                <Button key="follow" label="フォローする" variant="primary" onPress={() => void relate($, 'follow', profileName)} />
              )}
              <Button key={s.muted.includes(s.view.profile.id) ? 'unmute' : 'mute'} label={s.muted.includes(s.view.profile.id) ? 'ミュート解除' : 'ミュート'} plain dimColor onPress={() => void relate($, s.view?.kind === 'user' && s.muted.includes(s.view.profile.id) ? 'unmute' : 'mute', profileName)} />
              <Button key="their-likes" label="♡ いいね一覧" plain dimColor onPress={() => void showView($, loadLikes($, profileName))} />
            </Box>
          )}
          {s.view.kind === 'thread' && <Text dimColor>返信は古い順（直近7日分）</Text>}
          {s.view.kind === 'search' && <Text dimColor>直近7日分の検索結果</Text>}
          {s.view.kind === 'lists' &&
            (s.view.lists.length ? (
              <Box flexDirection="column" marginTop={1}>
                {s.view.lists.map(item => (
                  <Button key={`list-${item.id}`} plain onPress={() => void showView($, loadList($, item.id, item.name))}>
                    <Text bold>📋 {item.name}</Text>
                    <Text dimColor>
                      {item.isPrivate ? ' 🔒' : ''}
                      {item.members !== null ? ` · ${item.members}人` : ''}
                    </Text>
                  </Button>
                ))}
              </Box>
            ) : (
              <Text dimColor>リストがありません</Text>
            ))}
          {s.view.kind === 'trends' &&
            (s.view.trends.length ? (
              <Box flexDirection="column" marginTop={1}>
                {s.view.trends.map((trend, i) => (
                  <Button key={`trend-${i}`} plain onPress={() => void showView($, loadSearch($, trend.name))}>
                    <Text dimColor>{i + 1} · </Text>
                    <Text bold>{trend.name}</Text>
                    <Text dimColor>
                      {trend.posts ? ` · ${compactCount(trend.posts)}件` : ''}
                      {trend.category ? ` · ${trend.category}` : ''}
                    </Text>
                  </Button>
                ))}
              </Box>
            ) : (
              <Text dimColor>トレンドを取得できませんでした</Text>
            ))}
          <Text color="subtle">{rule}</Text>
        </Box>
      )}

      {s.qrFor && (
        <Box flexDirection="column" alignItems="center" paddingY={1}>
          {qrCard(elements, e.surface, s.qrFor)}
          <Box columnGap={2}>
            <Button key="qr-open" label="画像で開く" plain onPress={() => void qrCommand($, 'open')} />
            <Button key="qr-close" label="閉じる" plain dimColor onPress={() => setStatus($, { qrFor: null })} />
          </Box>
          <Text color="subtle">{rule}</Text>
        </Box>
      )}

      {s.mode === 'tags' && (
        <Box flexDirection="column">
          <Box columnGap={2} flexWrap="wrap">
            <Button key="tag-all" plain onPress={() => showTag($, null)}>
              <Text bold={s.activeTag === null} color={s.activeTag === null ? ACCENT : undefined} dimColor={s.activeTag !== null}>
                すべて
              </Text>
            </Button>
            {s.tags.map(tag => (
              <Button key={`tag-${tag}`} plain onPress={() => showTag($, tag)}>
                <Text bold={s.activeTag === tag} color={ACCENT} dimColor={s.activeTag !== tag}>
                  #{tag}
                </Text>
              </Button>
            ))}
          </Box>
          {Input && <Input key="tag-add" label="# " placeholder="ハッシュタグを登録" submitLabel="登録" onSubmit={value => void tagCommand($, `add ${value}`)} />}
          <Text color="subtle">{rule}</Text>
        </Box>
      )}

      {pending.isConfirming ? (
        <Box flexDirection="column" borderStyle="round" borderColor={ACCENT} paddingX={1}>
          <Box columnGap={1}>
            {avatar(Text, me, me)}
            <Box flexDirection="column" flexShrink={1}>
              <Text dimColor>{pending.replyTo ? `返信先: @${pending.replyTo.username}` : pending.quoteOf ? '引用してポストしますか？' : 'このままポストしますか？'}</Text>
              <Text>{richText(Text, pending.text)}</Text>
              {pending.images.length > 0 && <Text color={ACCENT}>🖼 {pending.images.map(path => path.split('/').pop()).join('  ')}</Text>}
              {pending.quoteOf && (
                <Box flexDirection="column" borderStyle="round" borderColor="subtle" paddingX={1}>
                  <Text>
                    <Text bold>{pending.quoteOf.name}</Text>
                    <Text dimColor> @{pending.quoteOf.username}</Text>
                  </Text>
                  <Text dimColor>{clip(pending.quoteOf.text, 120)}</Text>
                </Box>
              )}
            </Box>
          </Box>
          <Box justifyContent="space-between" marginTop={1}>
            <Text color={length > POST_LIMIT ? 'error' : undefined} dimColor={length <= POST_LIMIT}>
              {length > POST_LIMIT ? `${length}/${POST_LIMIT} · 長すぎます（X Premium以外）` : `${length}/${POST_LIMIT}`}
            </Text>
            <Box columnGap={2}>
              <Button key="post-cancel" label="取消" plain dimColor onPress={() => void cancelDraft($)} />
              <Button key="post-confirm" label={pending.isPosting ? 'ポスト中…' : pending.replyTo ? '返信' : 'ポストする'} variant="primary" onPress={() => void sendDraft($)} />
            </Box>
          </Box>
          {!s.canPost && <Text color="warning">ポストの権限がありません。`/x login` でログインし直すとポストできます。</Text>}
        </Box>
      ) : Input ? (
        <Box columnGap={1}>
          {avatar(Text, me, me)}
          <Box flexDirection="column" flexGrow={1} flexShrink={1}>
            {(pending.replyTo || pending.quoteOf) && (
              <Box columnGap={1}>
                <Text dimColor>
                  {pending.replyTo ? '返信先: ' : '引用: '}
                  <Text color={ACCENT}>@{pending.replyTo?.username ?? pending.quoteOf?.username}</Text>
                </Text>
                <Button key="reply-cancel" label="×" plain dimColor onPress={() => void cancelDraft($)} />
              </Box>
            )}
            <Input
              key="compose"
              placeholder={pending.replyTo ? '返信をポスト' : pending.quoteOf ? 'コメントを追加' : 'いまどうしてる？'}
              submitLabel={pending.replyTo ? '返信' : 'ポスト'}
              value={pending.text}
              onInput={value => void update($, draft, d => ({ ...EMPTY_DRAFT, ...d, text: value }))}
              onSubmit={value => {
              const parsed = parsePostArgs(value)
              void stageDraft($, parsed.text, parsed.images)
            }}
            />
            {pending.text && (
              <Text color={length > POST_LIMIT ? 'error' : undefined} dimColor={length <= POST_LIMIT}>
                {length}/{POST_LIMIT}
              </Text>
            )}
          </Box>
        </Box>
      ) : (
        <Text dimColor>ポストは `/x p 本文` で行えます。</Text>
      )}
      <Text color="subtle">{rule}</Text>

      {s.error && <Text color="error">⚠ {s.error}</Text>}
      {s.notice && <Text color={GREEN}>✓ {s.notice}</Text>}
      {s.newIds.length > 0 && list.length > s.newIds.length && (
        <Box justifyContent="center">
          <Text color={ACCENT}>↑ 新しいポスト {s.newIds.length}件</Text>
        </Box>
      )}

      {list.length === 0 && !s.isLoading && (
        <Box flexDirection="column" alignItems="center" paddingY={1}>
          <Text bold>
            {s.mode === 'home' ? 'まだポストがありません' : s.mode === 'mentions' ? 'まだ通知はありません' : s.tags.length === 0 && !s.activeTag ? 'ハッシュタグを登録しましょう' : 'まだポストがありません'}
          </Text>
          <Text dimColor>{s.mode === 'tags' && s.tags.length === 0 && !s.activeTag ? '上の欄か `/x tag add #タグ` で登録できます' : '「⟳ 更新」（r）で読み込みます'}</Text>
        </Box>
      )}
      {s.isLoading && list.length === 0 && (
        <Box justifyContent="center" paddingY={1}>
          <Text color={ACCENT}>⟳ 読み込み中…</Text>
        </Box>
      )}

      {list.map((post, index) => {
        const isSelected = index === cursor
        const isLiked = liked.has(targetOf(post))
        const shown = (n: number | undefined) => (post.hasNoCounts ? '' : count(n))
        const isReposted = s.reposted.includes(targetOf(post))
        const isBookmarked = s.mode === 'bookmarks' || s.bookmarked.includes(targetOf(post))
        const isMine = !post.repostedBy && post.username.toLowerCase() === me.toLowerCase()

        return (
          <Box key={post.id} flexDirection="column">
            {post.repostedBy && (
              <Box paddingLeft={4}>
                <Text dimColor>🔁 {post.repostedBy}さんがリポストしました</Text>
              </Box>
            )}
            <Box columnGap={1}>
              {avatar(Text, post.name, post.username)}
              <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                <Box>
                  {isSelected && <Text color={ACCENT}>▶ </Text>}
                  <Button key={`user-${post.id}`} plain onPress={() => void showView($, loadUser($, post.username))}>
                    <Text bold color={isSelected ? ACCENT : undefined}>
                      {post.name}
                    </Text>
                  </Button>
                  <Text wrap="truncate-end">
                    {post.isVerified && <Text color={ACCENT}> ☑</Text>}
                    <Text dimColor>
                      {' '}@{post.username} · {relativeTime(post.createdAt, now)}
                    </Text>
                    {isNew.has(post.id) && <Text color={ACCENT}> ●</Text>}
                  </Text>
                </Box>
                {post.replyingTo && post.replyingTo.length > 0 && (
                  <Text dimColor>
                    返信先: <Text color={ACCENT}>{post.replyingTo.map(name => `@${name}`).join(' ')}</Text>
                  </Text>
                )}
                <Text>{richText(Text, post.text, post.links)}</Text>
                {(post.images ?? []).length > 0 &&
                  (Image ? (
                    <Box columnGap={1} marginTop={1}>
                      {(post.images ?? []).slice(0, 2).map(image =>
                        ready.has(image.key) && mediaDir ? (
                          <Image
                            key={`img-${image.key}`}
                            source={{ file: `${mediaDir}/${image.key}.png`, format: 'png' }}
                            columns={(post.images ?? []).length > 1 ? Math.floor(imageColumns / 2) : imageColumns}
                            rows={imageRows(image)}
                            alt={image.alt || (image.kind === 'video' ? '動画' : '画像')}
                          />
                        ) : (
                          <Text dimColor>🖼 読み込み中…</Text>
                        ),
                      )}
                    </Box>
                  ) : (
                    <Box columnGap={2}>
                      {(post.images ?? []).slice(0, 4).map((image, i) => (
                        <Link
                          href={mediaVariant(image.url, 'jpg', 'medium')}
                          label={`${image.kind === 'video' ? '▶ 動画' : '🖼 画像'}${(post.images ?? []).length > 1 ? ` ${i + 1}` : ''}${image.alt ? `「${clip(image.alt, 20)}」` : ''}`}
                        />
                      ))}
                    </Box>
                  ))}
                {postBadges(post) && <Link href={postUrl(post)} label={postBadges(post)} />}
                {post.quote && (
                  <Box flexDirection="column" borderStyle="round" borderColor="subtle" paddingX={1}>
                    <Text wrap="truncate-end">
                      {avatar(Text, post.quote.name, post.quote.username)}
                      <Text bold> {post.quote.name}</Text>
                      {post.quote.isVerified && <Text color={ACCENT}> ☑</Text>}
                      <Text dimColor> @{post.quote.username}</Text>
                    </Text>
                    <Text>{richText(Text, clip(post.quote.text, 200), post.quote.links)}</Text>
                  </Box>
                )}
                <Box columnGap={4} marginTop={1}>
                  <Button key={`reply-${post.id}`} plain dimColor={!isSelected} onPress={() => startReply($, post)}>
                    💬 {shown(post.replies)}
                  </Button>
                  <Button key={`repost-${post.id}`} plain dimColor={!isReposted && s.repostAsk !== post.id} onPress={() => toggleRepost($, post, isReposted)}>
                    <Text color={isReposted ? GREEN : undefined}>🔁 {shown(post.reposts)}</Text>
                  </Button>
                  <Button key={`like-${post.id}`} plain dimColor={!isLiked} onPress={() => toggleLike($, post)}>
                    <Text color={isLiked ? PINK : undefined}>
                      {isLiked ? '♥' : '♡'} {shown(post.likes)}
                    </Text>
                  </Button>
                  <Button key={`bookmark-${post.id}`} plain dimColor={!isBookmarked} onPress={() => togglePostFlag($, post, 'bookmark')}>
                    <Text color={isBookmarked ? ACCENT : undefined}>{isBookmarked ? '🔖' : '🏷'}</Text>
                  </Button>
                  {post.views !== undefined && <Text dimColor>📊 {count(post.views)}</Text>}
                  <Button key={`thread-${post.id}`} label="💭" plain dimColor onPress={() => void showView($, loadThread($, post))} />
                  <Link href={postUrl(post)} label="↗" />
                  {isMine && <Button key={`delete-${post.id}`} label="🗑" plain dimColor onPress={() => setStatus($, { deleteAsk: s.deleteAsk === post.id ? null : post.id })} />}
                </Box>
                {s.deleteAsk === post.id && (
                  <Box columnGap={2}>
                    <Text color="error">このポストを削除しますか？取り消せません</Text>
                    <Button key={`delete-yes-${post.id}`} label="削除" variant="primary" onPress={() => void deletePost($, post)} />
                    <Button key={`delete-no-${post.id}`} label="やめる" plain dimColor onPress={() => setStatus($, { deleteAsk: null })} />
                  </Box>
                )}
                {s.repostAsk === post.id && (
                  <Box columnGap={2}>
                    <Button key={`repost-yes-${post.id}`} label="🔁 リポスト" variant="primary" onPress={() => toggleRepost($, post, true)} />
                    <Button key={`quote-${post.id}`} label="❝ 引用" onPress={() => startQuote($, post)} />
                    <Button key={`repost-no-${post.id}`} label="やめる" plain dimColor onPress={() => setStatus($, { repostAsk: null })} />
                  </Box>
                )}
              </Box>
            </Box>
            <Text color="subtle">{rule}</Text>
          </Box>
        )
      })}

      {list.length > 0 && (all.length > list.length || s.hasMore[s.mode]) && (
        <Box justifyContent="center">
          <Button key="older" label={s.isLoading ? '読み込み中…' : 'さらに表示'} hotkey="m" plain onPress={() => void showMore($, site, all.length, list.length)} />
        </Box>
      )}

      <Text color="subtle">{rule}</Text>
      <Box columnGap={2} flexWrap="wrap">
        <Button key="next" label="↓ 次" hotkey="j" plain dimColor onPress={() => moveCursor($, 1)} />
        <Button key="prev" label="↑ 前" hotkey="k" plain dimColor onPress={() => moveCursor($, -1)} />
        <Button key="sel-like" label="♡ いいね" hotkey="l" plain dimColor onPress={() => onSelected($, 'like')} />
        <Button key="sel-repost" label="🔁 リポスト" hotkey="t" plain dimColor onPress={() => onSelected($, 'repost')} />
        <Button key="sel-reply" label="💬 返信" hotkey="r" plain dimColor onPress={() => onSelected($, 'reply')} />
        <Button key="sel-open" label="↗ 開く" hotkey="o" plain dimColor onPress={() => onSelected($, 'open')} />
        <Button key="sel-user" label="👤 プロフィール" hotkey="p" plain dimColor onPress={() => onSelected($, 'user')} />
        <Button key="sel-thread" label="💭 スレッド" hotkey="s" plain dimColor onPress={() => onSelected($, 'thread')} />
        <Button key="sel-bookmark" label="🔖 保存" hotkey="b" plain dimColor onPress={() => onSelected($, 'bookmark')} />
        <Button key="sel-quote" label="❝ 引用" hotkey="w" plain dimColor onPress={() => onSelected($, 'quote')} />
      </Box>
      <Box columnGap={2} flexWrap="wrap">
        <Button key="refresh" label={s.isLoading ? '⟳ 更新中' : '⟳ 更新'} hotkey="u" plain dimColor onPress={() => void refreshTimeline($)} />
        <Button key="auto" label={s.autoMinutes > 0 ? `⏱ 自動 ${s.autoMinutes}分` : '⏱ 自動 OFF'} hotkey="a" plain dimColor onPress={() => setAuto($, nextAuto)} />
        <Button key="qr" label={s.qrFor ? '▣ QRを閉じる' : '▣ QR'} hotkey="q" plain dimColor onPress={() => (s.qrFor ? setStatus($, { qrFor: null }) : qrCommand($, ''))} />
        <Button key="logout" label="ログアウト" plain dimColor onPress={() => logout($)} />
      </Box>
    </Box>
  )
}

export const register: Register = (on, options) => {
  maxResults = clampResults(options.maxResults)
  defaultAutoMinutes = Math.max(0, Number(options.refreshMinutes) || 0)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'x-timeline',
      description: 'X（𝕏）のタイムライン・通知・投稿（show / mentions / post <本文> / auto <分> / login）',
      argumentHint: '[show|mentions|post <本文>|refresh|auto <分>|login|logout|client-id <ID>]',
      immediate: true,
    })
    // Claude can read what the person sees (summaries, questions about it)
    // from the posts already loaded: no X request, no cost, nothing written.
    await $.tool.register({
      name: 'read_timeline',
      description:
        'Read the X (Twitter) posts the x-timeline mod has already loaded for the user (home, notifications, hashtags, bookmarks, or the open thread/profile/search). Read-only: it makes no request to X. Use it when the user asks about, or wants a summary of, their timeline.',
      inputSchema: {
        type: 'object',
        properties: {
          tab: { type: 'string', enum: ['current', 'home', 'mentions', 'tags', 'bookmarks', 'view'], description: 'Which list; current is the one on screen.' },
          limit: { type: 'number', description: 'How many posts, newest first (1-100, default 30).' },
        },
      },
    })
    await $.command.register({
      name: 'x',
      description: '𝕏 ホーム⇄通知を切り替え（h ホーム · n 通知 · r 更新 · p 投稿 · a 自動）',
      argumentHint: '[h|n|r|p <本文>|send|a <分>|help]',
      immediate: true,
    })
    void (async () => {
      await detectPlatform($)
      tokens = await loadTokens($)
      await ensureMediaDir($)
      const kept = await $.store.get('autoMinutes')
      const autoMinutes = typeof kept === 'number' ? kept : defaultAutoMinutes
      await setStatus($, { auth: tokens ? 'signed-in' : 'signed-out', canPost: canPost(tokens), canLike: canLike(tokens), autoMinutes, tags: await loadTags($) })
      await openPane($)
      if (tokens && autoMinutes > 0) {
        await refreshTimeline($, 'home')
        await setAuto($, autoMinutes)
      }
    })()

    return next(e)
  })

  on('command.run', { command: 'x-timeline' }, async ($, e) => ({ text: await runCommand($, e.args, e.origin.kind, false) }))

  on('command.run', { command: 'x' }, async ($, e) => ({ text: await runCommand($, e.args, e.origin.kind, true) }))

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e) => drawTimeline($, e, e.props.bodyColumns, 'pane'))

  // A RegExp matcher: the tool's typed name exists only once the engine has
  // listed it, after the mod's first load.
  on('tool.call', { tool: /^mcp__x-timeline__read_timeline$/ }, async ($, e) => {
    // A tool's arguments ride the event itself, beside `tool`.
    const input = e as unknown as { tab?: string; limit?: number }
    const s = await readStatus($)
    const tab = (input.tab && input.tab !== 'current' && input.tab in s.unread ? input.tab : s.mode) as Mode
    const limit = Math.max(1, Math.min(100, Math.round(Number(input.limit) || 30)))
    const list = (await readList($, tab)).slice(0, limit)
    const now = await $.clock.now()
    const lines = list.map(
      post =>
        `- ${post.repostedBy ? `(${post.repostedBy} reposted) ` : ''}${post.name} @${post.username} · ${relativeTime(post.createdAt, now)} · ♡${post.likes ?? 0} 🔁${post.reposts ?? 0}\n  ${post.text.replace(/\n/g, ' ')}${post.quote ? `\n  [quoting @${post.quote.username}: ${post.quote.text.replace(/\n/g, ' ')}]` : ''}\n  ${postUrl(post)}`,
    )
    const text = list.length
      ? `${tab === 'view' && s.view ? viewTitle(s.view) : TAB_LABELS[tab]} (${list.length} posts, as loaded)\n${lines.join('\n')}`
      : 'No posts are loaded for that tab. The user can load them with /x (and /x 2, /x 3, /x 4 for the other tabs).'

    return { result: { text }, text }
  })

  // `/x qr` draws its code as a picture in the chat, every time it ran.
  on('ui.render', { component: 'CommandOutput', props: { command: ['x', 'x-timeline'], args: /^\s*(qr|QR)\b/ } }, ($, e, next) => {
    const username = /https:\/\/x\.com\/([A-Za-z0-9_]{1,15})）/.exec(e.props.text)?.[1]
    if (!username || /\bopen\b/.test(e.props.args)) return next(e)
    const elements = $.ui.resolve(e)
    const { Box } = elements

    return (
      <Box flexDirection="column" alignItems="flex-start" paddingY={1}>
        {qrCard(elements, e.surface, username)}
      </Box>
    )
  })

  // The newest listing a command printed in the chat is drawn live: its tabs,
  // likes and replies work in place. Older ones stay as the text they were.
  on('ui.render', { component: 'CommandOutput', props: { command: ['x', 'x-timeline'] } }, async ($, e, next) => {
    const s = await readStatus($)
    if (!s.liveTail || !e.props.text.endsWith(s.liveTail)) return next(e)

    return drawTimeline($, e, Math.max(40, (e.viewport?.columns ?? 100) - 4), 'chat')
  })
}

