// A small QR Code encoder: byte mode, error correction level M, versions 1-6
// (up to 106 bytes, plenty for a profile URL). Follows ISO/IEC 18004 the way
// Project Nayuki's reference encoder lays it out. No engine calls here.

const ECC_PER_BLOCK_M = [-1, 10, 16, 26, 18, 24, 16]
const BLOCKS_M = [-1, 1, 1, 1, 2, 2, 4]
const MAX_VERSION = 6

export type QrMatrix = boolean[][]

function rawDataModules(version: number): number {
  let result = (16 * version + 128) * version + 64
  if (version >= 2) {
    const align = Math.floor(version / 7) + 2
    result -= (25 * align - 10) * align - 55
  }

  return result
}

function dataCodewords(version: number): number {
  return Math.floor(rawDataModules(version) / 8) - (ECC_PER_BLOCK_M[version] ?? 0) * (BLOCKS_M[version] ?? 0)
}

function gfMultiply(x: number, y: number): number {
  let z = 0
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d)
    z ^= ((y >>> i) & 1) * x
  }

  return z & 0xff
}

function rsDivisor(degree: number): number[] {
  const result = new Array<number>(degree).fill(0)
  result[degree - 1] = 1
  let root = 1
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      result[j] = gfMultiply(result[j] ?? 0, root)
      if (j + 1 < degree) result[j] = (result[j] ?? 0) ^ (result[j + 1] ?? 0)
    }
    root = gfMultiply(root, 0x02)
  }

  return result
}

function rsRemainder(data: number[], divisor: number[]): number[] {
  const result = new Array<number>(divisor.length).fill(0)
  for (const byte of data) {
    const factor = byte ^ (result.shift() ?? 0)
    result.push(0)
    divisor.forEach((coef, i) => {
      result[i] = (result[i] ?? 0) ^ gfMultiply(coef, factor)
    })
  }

  return result
}

function withEcc(data: number[], version: number): number[] {
  const blocks = BLOCKS_M[version] ?? 1
  const eccLen = ECC_PER_BLOCK_M[version] ?? 0
  const raw = Math.floor(rawDataModules(version) / 8)
  const shortBlocks = blocks - (raw % blocks)
  const shortLen = Math.floor(raw / blocks)
  const divisor = rsDivisor(eccLen)
  const all: number[][] = []
  let k = 0
  for (let i = 0; i < blocks; i++) {
    const dat = data.slice(k, k + shortLen - eccLen + (i < shortBlocks ? 0 : 1))
    k += dat.length
    const ecc = rsRemainder(dat, divisor)
    if (i < shortBlocks) dat.push(0)
    all.push(dat.concat(ecc))
  }
  const result: number[] = []
  const width = all[0]?.length ?? 0
  for (let i = 0; i < width; i++) {
    all.forEach((block, j) => {
      if (i !== shortLen - eccLen || j >= shortBlocks) result.push(block[i] ?? 0)
    })
  }

  return result
}

function encodeData(bytes: Uint8Array): { version: number; codewords: number[] } {
  for (let version = 1; version <= MAX_VERSION; version++) {
    const capacityBits = dataCodewords(version) * 8
    const bits: number[] = []
    const push = (value: number, length: number) => {
      for (let i = length - 1; i >= 0; i--) bits.push((value >>> i) & 1)
    }
    push(0b0100, 4)
    push(bytes.length, 8)
    bytes.forEach(byte => push(byte, 8))
    if (bits.length > capacityBits) continue
    push(0, Math.min(4, capacityBits - bits.length))
    push(0, (8 - (bits.length % 8)) % 8)
    for (let pad = 0xec; bits.length < capacityBits; pad ^= 0xec ^ 0x11) push(pad, 8)
    const codewords: number[] = []
    for (let i = 0; i < bits.length; i += 8) {
      let byte = 0
      for (let j = 0; j < 8; j++) byte = (byte << 1) | (bits[i + j] ?? 0)
      codewords.push(byte)
    }

    return { version, codewords: withEcc(codewords, version) }
  }
  throw new Error('QRコードに入りきらない長さです')
}

function alignmentPositions(version: number, size: number): number[] {
  if (version === 1) return []
  const count = Math.floor(version / 7) + 2
  const step = Math.ceil((version * 4 + 4) / (count * 2 - 2)) * 2
  const result = [6]
  for (let pos = size - 7; result.length < count; pos -= step) result.splice(1, 0, pos)

  return result
}

const MASKS: Array<(x: number, y: number) => boolean> = [
  (x, y) => (x + y) % 2 === 0,
  (_x, y) => y % 2 === 0,
  x => x % 3 === 0,
  (x, y) => (x + y) % 3 === 0,
  (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,
  (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
  (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
  (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
]

function penalty(m: QrMatrix): number {
  const size = m.length
  let score = 0
  const runs = (line: boolean[]) => {
    let run = 1
    for (let i = 1; i <= line.length; i++) {
      if (i < line.length && line[i] === line[i - 1]) {
        run++
        continue
      }
      if (run >= 5) score += run - 2
      run = 1
    }
  }
  for (let y = 0; y < size; y++) runs(m[y] ?? [])
  for (let x = 0; x < size; x++) runs(m.map(row => row[x] ?? false))
  for (let y = 0; y + 1 < size; y++) {
    for (let x = 0; x + 1 < size; x++) {
      const c = m[y]?.[x]
      if (c === m[y]?.[x + 1] && c === m[y + 1]?.[x] && c === m[y + 1]?.[x + 1]) score += 3
    }
  }
  const finderLike = [true, false, true, true, true, false, true]
  const scan = (line: boolean[]) => {
    for (let i = 0; i + 7 <= line.length; i++) {
      if (!finderLike.every((v, j) => line[i + j] === v)) continue
      const before = line.slice(Math.max(0, i - 4), i)
      const after = line.slice(i + 7, i + 11)
      if ((i < 4 || before.every(v => !v)) || (i + 11 > line.length || after.every(v => !v))) score += 40
    }
  }
  for (let y = 0; y < size; y++) scan(m[y] ?? [])
  for (let x = 0; x < size; x++) scan(m.map(row => row[x] ?? false))
  const dark = m.reduce((n, row) => n + row.filter(Boolean).length, 0)
  const total = size * size
  score += Math.floor(Math.abs(dark * 20 - total * 10) / total) * 10

  return score
}

export function encodeQr(text: string): QrMatrix {
  const { version, codewords } = encodeData(new TextEncoder().encode(text))
  const size = version * 4 + 17
  const grid: QrMatrix = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const fixed: QrMatrix = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const set = (x: number, y: number, dark: boolean) => {
    const row = grid[y]
    const fixedRow = fixed[y]
    if (!row || !fixedRow || x < 0 || x >= size) return
    row[x] = dark
    fixedRow[x] = true
  }

  for (let i = 0; i < size; i++) {
    set(6, i, i % 2 === 0)
    set(i, 6, i % 2 === 0)
  }
  for (const [cx, cy] of [
    [3, 3],
    [size - 4, 3],
    [3, size - 4],
  ] as const) {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const dist = Math.max(Math.abs(dx), Math.abs(dy))
        const x = cx + dx
        const y = cy + dy
        if (x >= 0 && x < size && y >= 0 && y < size) set(x, y, dist !== 2 && dist !== 4)
      }
    }
  }
  const aligns = alignmentPositions(version, size)
  aligns.forEach((ay, i) =>
    aligns.forEach((ax, j) => {
      const isCorner = (i === 0 && j === 0) || (i === 0 && j === aligns.length - 1) || (i === aligns.length - 1 && j === 0)
      if (isCorner) return
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) set(ax + dx, ay + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1)
    }),
  )
  const drawFormat = (mask: number) => {
    const data = (0 << 3) | mask // level M is 00
    let rem = data
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537)
    const bits = ((data << 10) | rem) ^ 0x5412
    const bit = (i: number) => ((bits >>> i) & 1) !== 0
    for (let i = 0; i <= 5; i++) set(8, i, bit(i))
    set(8, 7, bit(6))
    set(8, 8, bit(7))
    set(7, 8, bit(8))
    for (let i = 9; i < 15; i++) set(14 - i, 8, bit(i))
    for (let i = 0; i < 8; i++) set(size - 1 - i, 8, bit(i))
    for (let i = 8; i < 15; i++) set(8, size - 15 + i, bit(i))
    set(8, size - 8, true)
  }
  drawFormat(0)

  let i = 0
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5
    for (let vert = 0; vert < size; vert++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j
        const upward = ((right + 1) & 2) === 0
        const y = upward ? size - 1 - vert : vert
        const row = grid[y]
        if (row && !fixed[y]?.[x] && i < codewords.length * 8) {
          row[x] = (((codewords[i >>> 3] ?? 0) >>> (7 - (i & 7))) & 1) !== 0
          i++
        }
      }
    }
  }

  const masked = (mask: number): QrMatrix => {
    const test = MASKS[mask] ?? (() => false)
    const out = grid.map((row, y) => row.map((dark, x) => (fixed[y]?.[x] ? dark : dark !== test(x, y))))
    const keep = grid.map(row => [...row])
    grid.splice(0, size, ...out)
    drawFormat(mask)
    const result = grid.map(row => [...row])
    grid.splice(0, size, ...keep)

    return result
  }
  let best = masked(0)
  let bestScore = penalty(best)
  for (let mask = 1; mask < 8; mask++) {
    const candidate = masked(mask)
    const score = penalty(candidate)
    if (score < bestScore) {
      best = candidate
      bestScore = score
    }
  }

  return best
}

function withQuietZone(m: QrMatrix, quiet: number): QrMatrix {
  const size = m.length + quiet * 2
  return Array.from({ length: size }, (_, y) =>
    Array.from({ length: size }, (_, x) => m[y - quiet]?.[x - quiet] ?? false),
  )
}

// Two module rows per text row with half blocks. `darkGlyph` true draws the
// dark modules as glyphs (for black text on a white background); false
// draws the light ones (for light text on a dark background).
export function qrRows(m: QrMatrix, darkGlyph: boolean, quiet = 2): string[] {
  const grid = withQuietZone(m, quiet)
  const rows: string[] = []
  for (let y = 0; y < grid.length; y += 2) {
    let line = ''
    for (let x = 0; x < grid.length; x++) {
      const top = (grid[y]?.[x] ?? false) === darkGlyph
      const bottom = y + 1 < grid.length ? (grid[y + 1]?.[x] ?? false) === darkGlyph : !darkGlyph ? true : false
      line += top && bottom ? '█' : top ? '▀' : bottom ? '▄' : ' '
    }
    rows.push(line)
  }

  return rows
}

export function qrSvg(m: QrMatrix, quiet = 4, scale = 10): string {
  const size = m.length + quiet * 2
  const rects: string[] = []
  m.forEach((row, y) =>
    row.forEach((dark, x) => {
      if (dark) rects.push(`M${x + quiet} ${y + quiet}h1v1h-1z`)
    }),
  )

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size * scale}" height="${size * scale}" shape-rendering="crispEdges"><rect width="${size}" height="${size}" fill="#fff"/><path d="${rects.join('')}" fill="#000"/></svg>\n`
}

