import type { ListInfo, Post, Profile, TrendInfo } from '../types'

// Pure helpers for X API v2 and OAuth 2.0 (PKCE). No engine calls here.

export const API = 'https://api.x.com'
export const AUTHORIZE = 'https://x.com/i/oauth2/authorize'
// Every scope a feature of the mod uses; never DMs. A token without one
// asks the person to log in again for that feature only.
export const SCOPES = [
  'tweet.read',
  'tweet.write',
  'users.read',
  'like.read',
  'like.write',
  'bookmark.read',
  'bookmark.write',
  'follows.read',
  'follows.write',
  'mute.write',
  'list.read',
  'media.write',
  'offline.access',
].join(' ')
export const CALLBACK_PORT = 8976
export const REDIRECT_URI = `http://127.0.0.1:${CALLBACK_PORT}/callback`

export type Tokens = {
  accessToken: string
  refreshToken: string | null
  expiresAt: number
  clientId: string | null
  scope: string
}

export type HttpLike = {
  status: number
  headers: Record<string, string>
  text: string
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'

export function base64url(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = ((bytes[i] ?? 0) << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += ALPHABET.charAt((n >> 18) & 63) + ALPHABET.charAt((n >> 12) & 63)
    if (i + 1 < bytes.length) out += ALPHABET.charAt((n >> 6) & 63)
    if (i + 2 < bytes.length) out += ALPHABET.charAt(n & 63)
  }

  return out
}

export function fromBase64url(text: string): Uint8Array {
  const out: number[] = []
  let buffer = 0
  let bits = 0
  for (const char of text) {
    const value = ALPHABET.indexOf(char)
    if (value < 0) throw new Error('invalid base64url')
    buffer = (buffer << 6) | value
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out.push((buffer >> bits) & 255)
    }
  }

  return new Uint8Array(out)
}

export function encodeSecret(tokens: Tokens): string {
  return base64url(new TextEncoder().encode(JSON.stringify(tokens)))
}

export function decodeSecret(text: string): Tokens | null {
  try {
    const value = JSON.parse(new TextDecoder().decode(fromBase64url(text.trim())))
    if (typeof value?.accessToken !== 'string' || typeof value?.expiresAt !== 'number') return null

    return {
      accessToken: value.accessToken,
      refreshToken: typeof value.refreshToken === 'string' ? value.refreshToken : null,
      expiresAt: value.expiresAt,
      clientId: typeof value.clientId === 'string' && isClientId(value.clientId) ? value.clientId : null,
      scope: typeof value.scope === 'string' ? value.scope : '',
    }
  } catch {
    return null
  }
}

function randomBytes(length: number): Uint8Array {
  // A CSPRNG only: PKCE and state must not fall back to Math.random.
  return crypto.getRandomValues(new Uint8Array(length))
}

export async function createPkce(): Promise<{ verifier: string; challenge: string; state: string }> {
  const verifier = base64url(randomBytes(32))
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier))

  return { verifier, challenge: base64url(new Uint8Array(digest)), state: base64url(randomBytes(16)) }
}

export function formEncode(params: Record<string, string>): string {
  return Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&')
}

export function parseQuery(query: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const part of query.replace(/^\?/, '').split('&')) {
    if (!part) continue
    const [key = '', value = ''] = part.split('=')
    out[decodeURIComponent(key.replace(/\+/g, ' '))] = decodeURIComponent(value.replace(/\+/g, ' '))
  }

  return out
}

export function authorizeUrl(clientId: string, challenge: string, state: string): string {
  return `${AUTHORIZE}?${formEncode({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: REDIRECT_URI,
    scope: SCOPES,
    state,
    code_challenge: challenge,
    code_challenge_method: 'S256',
  })}`
}

export function isClientId(value: string): boolean {
  return /^[A-Za-z0-9_-]{10,100}$/.test(value)
}

// Reads `client-id <ID>`'s argument as people paste it: wrapped in <> or
// quotes, or with a following `/x-timeline login` line pasted alongside.
export function parseClientIdArgs(args: string): { id: string | null; alsoLogin: boolean } {
  const [first = '', ...more] = args.split(/\r?\n/)
  const token = (first.trim().split(/\s+/)[0] ?? '').replace(/^[<"'「]+|[>"'」]+$/g, '')

  return {
    id: isClientId(token) ? token : null,
    alsoLogin: more.some(line => /^\/?x-timeline\s+login\s*$/.test(line.trim())),
  }
}

export function tokensFrom(body: unknown, now: number, clientId: string): Tokens {
  const value = body as { access_token?: unknown; refresh_token?: unknown; expires_in?: unknown; scope?: unknown }
  if (typeof value?.access_token !== 'string') throw new Error('トークン応答の形式が不正です')
  const seconds = typeof value.expires_in === 'number' ? value.expires_in : 7200

  return {
    accessToken: value.access_token,
    refreshToken: typeof value.refresh_token === 'string' ? value.refresh_token : null,
    expiresAt: now + seconds * 1000,
    clientId,
    scope: typeof value.scope === 'string' ? value.scope : '',
  }
}

export function hasScope(tokens: Tokens | null, scope: string): boolean {
  return tokens !== null && tokens.scope.split(/\s+/).includes(scope)
}

export function canPost(tokens: Tokens | null): boolean {
  return hasScope(tokens, 'tweet.write')
}

export function canLike(tokens: Tokens | null): boolean {
  return hasScope(tokens, 'like.write')
}

export const TWEET_FIELDS = 'created_at,note_tweet,public_metrics,referenced_tweets,in_reply_to_user_id,entities,attachments,conversation_id'

// X's weighted length: most Latin text counts 1, CJK and emoji 2, a URL 23.
export const POST_LIMIT = 280

export function weightedLength(text: string): number {
  let total = 0
  const withoutUrls = text.replace(/https?:\/\/\S+/g, () => {
    total += 23

    return ''
  })
  for (const char of withoutUrls) {
    const code = char.codePointAt(0) ?? 0
    const isLight =
      code <= 4351 || (code >= 8192 && code <= 8205) || (code >= 8208 && code <= 8223) || (code >= 8242 && code <= 8247)
    total += isLight ? 1 : 2
  }

  return total
}

export function postUrl(post: Post): string {
  return `https://x.com/${post.username}/status/${post.targetId ?? post.id}`
}

export const USER_FIELDS = 'name,username,verified,verified_type'

// A post's text in pieces: plain words, and the links X draws in blue.
export type Segment = { kind: 'text' | 'url' | 'mention' | 'hashtag'; text: string; href?: string }

export function segments(text: string, links?: Post['links']): Segment[] {
  const out: Segment[] = []
  const pattern = /(https?:\/\/\S+)|(@[A-Za-z0-9_]{1,15})|([#＃][\p{L}\p{N}_]+)/gu
  let last = 0
  for (const match of text.matchAll(pattern)) {
    const at = match.index ?? 0
    if (at > last) out.push({ kind: 'text', text: text.slice(last, at) })
    const [whole, url, mention] = match
    // A t.co link reads as X draws it: the target's short form, linked whole.
    if (url) out.push({ kind: 'url', text: links?.[whole]?.display ?? whole, href: links?.[whole]?.href ?? whole })
    else if (mention) out.push({ kind: 'mention', text: whole, href: `https://x.com/${whole.slice(1)}` })
    else out.push({ kind: 'hashtag', text: whole, href: `https://x.com/hashtag/${encodeURIComponent(whole.slice(1))}` })
    last = at + whole.length
  }
  if (last < text.length) out.push({ kind: 'text', text: text.slice(last) })

  return out
}

function escapeMarkdown(text: string): string {
  return text.replace(/([\\`*_[\]<>|~])/g, '\\$1').replace(/^(\s*)([#>+-]|\d+\.)(\s)/gm, '$1\\$2$3')
}

export function markdownBody(text: string, links?: Post['links']): string {
  return segments(text, links)
    .map(part =>
      part.kind === 'text'
        ? escapeMarkdown(part.text)
        : part.kind === 'url' && part.text === part.href
          ? part.text
          : `[${escapeMarkdown(part.text)}](${part.href})`,
    )
    .join('')
    .split('\n')
    .join('  \n')
}

// X's Web Intents: one click opens X's own reply, repost or like screen
// for the post, signed in as the person, with no API call of ours.
export function intentUrl(kind: 'reply' | 'repost' | 'like', post: Post): string {
  const id = post.targetId ?? post.id
  if (kind === 'reply') return `https://x.com/intent/post?in_reply_to=${id}`

  return `https://x.com/intent/${kind === 'repost' ? 'retweet' : 'like'}?tweet_id=${id}`
}

export function metricsLine(post: Post): string {
  // A repost's own counts are the wrapper's, not the original's: none shown.
  const n = (value: number | undefined) => (post.hasNoCounts ? '' : ` ${compactCount(value ?? 0)}`)
  const parts = [
    `[💬${n(post.replies)}](${intentUrl('reply', post)})`,
    `[🔁${n(post.reposts)}](${intentUrl('repost', post)})`,
    `[♡${n(post.likes)}](${intentUrl('like', post)})`,
  ]
  if (post.views !== undefined && !post.hasNoCounts) parts.push(`📊 ${compactCount(post.views)}`)

  return parts.join('　　')
}

export function imagesMarkdown(post: Post): string {
  return (post.images ?? [])
    .slice(0, 4)
    .map(image => `[![${escapeMarkdown(image.alt || (image.kind === 'video' ? '動画' : '画像'))}](${mediaVariant(image.url, 'jpg', 'small')})](${postUrl(post)})`)
    .join(' ')
}

export function clip(text: string, length: number): string {
  const chars = [...text]

  return chars.length > length ? `${chars.slice(0, length).join('')}…` : text
}

export function postBadges(post: Post): string {
  const images = post.images ?? []
  const videos = images.filter(image => image.kind === 'video').length
  // Media drawn as pictures needs no badge but a video's; media X sent no
  // picture for keeps the count.
  const media = images.length > 0 ? (videos > 0 ? `▶ 動画${videos > 1 ? ` ${videos}本` : ''}` : '') : post.media ? `🖼 ${post.media === 1 ? '画像' : `画像 ${post.media}枚`}` : ''

  return [media, post.isQuote && !post.quote ? '❝ 引用ポスト' : '']
    .filter(Boolean)
    .join('　')
}

export function postText(post: Post, now: number, index?: number): string {
  const number = index === undefined ? '' : `\`${index}\` `
  const replying = post.replyingTo?.length ? [`<sub>返信先: ${post.replyingTo.map(name => `[@${escapeMarkdown(name)}](https://x.com/${name})`).join(' ')}</sub>`] : []
  const badges = postBadges(post)
  const head = [
    ...(post.repostedBy ? [`🔁 _${escapeMarkdown(post.repostedBy)}さんがリポストしました_`] : []),
    `${number}**${escapeMarkdown(post.name)}**${post.isVerified ? ' ☑︎' : ''} @${escapeMarkdown(post.username)} · ${relativeTime(post.createdAt, now)}`,
    ...replying,
    markdownBody(post.text, post.links),
    ...(post.images?.length ? [imagesMarkdown(post)] : []),
    ...(badges ? [`[${badges}](${postUrl(post)})`] : []),
  ]
  const quote = post.quote
    ? `\n\n> **${escapeMarkdown(post.quote.name)}**${post.quote.isVerified ? ' ☑︎' : ''} @${escapeMarkdown(post.quote.username)}  \n> ${markdownBody(clip(post.quote.text, 160), post.quote.links).split('  \n').join('  \n> ')}`
    : ''

  return `${head.join('  \n')}${quote}\n\n${metricsLine(post)}　　[↗ 開く](${postUrl(post)})`
}

function decodeEntities(text: string): string {
  return text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
}

type TimelineItem = {
  id: string
  text: string
  created_at?: string
  author_id?: string
  in_reply_to_user_id?: string
  conversation_id?: string
  note_tweet?: { text?: string; entities?: { urls?: UrlEntity[] } }
  public_metrics?: { like_count?: number; retweet_count?: number; reply_count?: number; impression_count?: number }
  referenced_tweets?: Array<{ type: string; id: string }>
  attachments?: { media_keys?: string[] }
  entities?: { urls?: UrlEntity[] }
}

type UrlEntity = { url?: string; expanded_url?: string; display_url?: string }

const LEADING_MENTIONS = /^((?:@[A-Za-z0-9_]{1,15}\s+)+)/

// Linked t.co URLs to what X shows for them; media links are dropped, as X
// draws the media itself rather than its link.
function linksOf(item: TimelineItem): { links: Post['links']; mediaUrls: Set<string> } {
  const links: NonNullable<Post['links']> = {}
  const mediaUrls = new Set<string>()
  // A long post's links are on its note, the rest on the post itself.
  for (const entity of [...(item.entities?.urls ?? []), ...(item.note_tweet?.entities?.urls ?? [])]) {
    if (!entity.url) continue
    const href = entity.expanded_url ?? entity.url
    if (/^https:\/\/(x|twitter)\.com\/[^/]+\/status\/\d+\/(photo|video)\//.test(href)) mediaUrls.add(entity.url)
    else links[entity.url] = { display: entity.display_url ?? href, href }
  }

  return { links, mediaUrls }
}

type TimelineUser = { id: string; username: string; name: string; verified?: boolean; verified_type?: string }

type TimelineMedia = { media_key: string; type: string; url?: string; preview_image_url?: string; alt_text?: string; width?: number; height?: number }

type TimelineBody = {
  data?: TimelineItem[]
  includes?: { users?: TimelineUser[]; tweets?: TimelineItem[]; media?: TimelineMedia[] }
}

// Only X's own image host is fetched or shown.
export function isMediaUrl(url: string): boolean {
  return /^https:\/\/pbs\.twimg\.com\/[A-Za-z0-9_./-]+$/.test(url.split('?')[0] ?? '')
}

function imagesOf(item: TimelineItem, media: Map<string, TimelineMedia>): NonNullable<Post['images']> {
  return (item.attachments?.media_keys ?? []).flatMap(key => {
    const found = media.get(key)
    const url = found?.url ?? found?.preview_image_url
    if (!found || !url || !isMediaUrl(url)) return []

    return [{ key, url, alt: found.alt_text ?? '', kind: found.type === 'photo' ? ('photo' as const) : ('video' as const), width: found.width ?? 0, height: found.height ?? 0 }]
  })
}

// A smaller rendition from X's image host, as a PNG for terminals.
export function mediaVariant(url: string, format: 'png' | 'jpg', size: 'small' | 'medium'): string {
  const base = url.split('?')[0] ?? url
  const stem = base.replace(/\.(jpg|jpeg|png|webp)$/i, '')

  return `${stem}?format=${format}&name=${size}`
}

const REPOST_PREFIX = /^RT @([A-Za-z0-9_]{1,15}): /
export const EXPANSIONS = 'author_id,referenced_tweets.id,referenced_tweets.id.author_id,attachments.media_keys'
export const MEDIA_FIELDS = 'type,url,preview_image_url,alt_text,width,height'

function isVerified(user: TimelineUser | undefined): boolean {
  return Boolean(user?.verified || (user?.verified_type && user.verified_type !== 'none'))
}

// One post as X draws it, without what wraps it (a repost) or what it
// quotes; `quotedId` drops the link to the quoted post from the text.
function toPost(item: TimelineItem, users: Map<string, TimelineUser>, quotedId?: string, media: Map<string, TimelineMedia> = new Map()): Post {
  const user = item.author_id ? users.get(item.author_id) : undefined
  const { links, mediaUrls } = linksOf(item)
  let text = decodeEntities(item.note_tweet?.text ?? item.text)
  // A media link goes with the space before it, so no gap is left.
  const drop = (url: string) => {
    text = text.includes(` ${url}`) ? text.replace(` ${url}`, '') : text.replace(url, '')
  }
  for (const url of mediaUrls) drop(url)
  if (quotedId) {
    for (const [url, link] of Object.entries(links ?? {})) {
      if (link.href.includes(`/status/${quotedId}`)) drop(url)
    }
  }
  text = text.trim()
  // A reply's leading mentions are drawn as "返信先" rather than as text.
  const leading = item.in_reply_to_user_id ? LEADING_MENTIONS.exec(text) : null
  const replyingTo = leading?.[1] ? leading[1].trim().split(/\s+/).map(name => name.slice(1)) : undefined
  if (leading?.[1] && text.length > leading[1].length) text = text.slice(leading[1].length)
  const metrics = item.public_metrics ?? {}

  return {
    id: item.id,
    text,
    createdAt: item.created_at ?? '',
    username: user?.username ?? 'i',
    name: user?.name ?? '(不明)',
    likes: metrics.like_count ?? 0,
    reposts: metrics.retweet_count ?? 0,
    replies: metrics.reply_count ?? 0,
    views: metrics.impression_count,
    isVerified: isVerified(user),
    isReply: Boolean(item.in_reply_to_user_id),
    replyingTo,
    links,
    media: item.attachments?.media_keys?.length ?? 0,
    isQuote: item.referenced_tweets?.some(ref => ref.type === 'quoted') ?? false,
    conversationId: item.conversation_id,
    images: imagesOf(item, media),
  }
}

function withQuote(item: TimelineItem, users: Map<string, TimelineUser>, tweets: Map<string, TimelineItem>, media: Map<string, TimelineMedia>): Post {
  const quotedId = item.referenced_tweets?.find(ref => ref.type === 'quoted')?.id
  const quoted = quotedId ? tweets.get(quotedId) : undefined
  const post = toPost(item, users, quoted ? quotedId : undefined, media)
  if (!quoted) return post
  const inner = toPost(quoted, users, undefined, media)

  return { ...post, quote: { id: inner.id, name: inner.name, username: inner.username, text: inner.text, isVerified: inner.isVerified, links: inner.links } }
}

export function parseTimeline(body: unknown): Post[] {
  const value = body as TimelineBody
  const users = new Map((value?.includes?.users ?? []).map(user => [user.id, user]))
  const tweets = new Map((value?.includes?.tweets ?? []).map(tweet => [tweet.id, tweet]))
  const media = new Map((value?.includes?.media ?? []).map(one => [one.media_key, one]))

  return (value?.data ?? []).map(item => {
    const wrapper = toPost(item, users, undefined, media)
    const repostOf = item.referenced_tweets?.find(ref => ref.type === 'retweeted')?.id
    const original = repostOf ? tweets.get(repostOf) : undefined
    // A repost reads as its original, the reposter in the header; it keeps
    // its own id (the timeline's order) and acts on the original's.
    if (original) return { ...withQuote(original, users, tweets, media), id: item.id, targetId: original.id, repostedBy: wrapper.name }
    const repost = repostOf ? REPOST_PREFIX.exec(wrapper.text) : null
    if (repost?.[1]) {
      return {
        ...wrapper,
        username: repost[1],
        name: repost[1],
        text: wrapper.text.slice(repost[0].length),
        targetId: repostOf,
        repostedBy: wrapper.name,
        isReply: false,
        isVerified: false,
        views: undefined,
        hasNoCounts: true,
      }
    }

    return withQuote(item, users, tweets, media)
  })
}

export function targetOf(post: Post): string {
  return post.targetId ?? post.id
}

export function mergePosts(fresh: Post[], current: Post[], limit: number): Post[] {
  // One row per post: a second repost of it, or the post and a repost of
  // it, keep the newest only.
  const seen = new Set<string>()
  const out: Post[] = []
  for (const post of [...fresh, ...current]) {
    if (seen.has(post.id) || seen.has(targetOf(post))) continue
    seen.add(post.id)
    seen.add(targetOf(post))
    out.push(post)
  }

  return out.slice(0, limit)
}

export function clampResults(value: unknown): number {
  const n = Math.round(Number(value))

  return Number.isFinite(n) ? Math.min(100, Math.max(5, n)) : 20
}

export function refreshIntervalMs(value: unknown): number {
  const minutes = Number(value)
  if (!Number.isFinite(minutes) || minutes <= 0) return 0

  return Math.max(5, minutes) * 60_000
}

function clock(ms: number): string {
  const date = new Date(ms)

  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`
}

export function relativeTime(iso: string, now: number): string {
  const then = Date.parse(iso)
  if (!Number.isFinite(then)) return ''
  const seconds = Math.max(0, Math.round((now - then) / 1000))
  if (seconds < 60) return `${seconds}秒`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}分`
  if (seconds < 86_400) return `${Math.floor(seconds / 3600)}時間`
  if (seconds < 7 * 86_400) return `${Math.floor(seconds / 86_400)}日`
  const date = new Date(then)

  return `${date.getMonth() + 1}月${date.getDate()}日`
}

export function compactCount(n: number): string {
  if (n >= 100_000_000) return `${(n / 100_000_000).toFixed(1).replace(/\.0$/, '')}億`
  if (n >= 10_000) return `${(n / 10_000).toFixed(1).replace(/\.0$/, '')}万`

  return n.toLocaleString('en-US')
}

export function describeApiError(res: HttpLike): string {
  let detail = ''
  try {
    const body = JSON.parse(res.text)
    detail = String(body?.detail ?? body?.error_description ?? body?.errors?.[0]?.message ?? body?.title ?? '')
  } catch {
    // not JSON
  }
  detail = detail.slice(0, 300)
  const suffix = detail ? `（${detail}）` : ''

  if (res.status === 429) {
    const reset = Number(res.headers['x-rate-limit-reset'])

    return Number.isFinite(reset) && reset > 0
      ? `レート制限中です。${clock(reset * 1000)}以降に再試行してください`
      : 'レート制限中です。しばらく待って再試行してください'
  }
  if (res.status === 402) return `X APIのクレジットが不足しています。Developer Consoleを確認してください${suffix}`
  if (res.status === 403) return `X APIへのアクセスが拒否されました。アプリの権限とプランを確認してください${suffix}`

  return `X APIエラー ${res.status}${suffix}`
}

// One-shot loopback listener for the OAuth redirect: binds 127.0.0.1 only,
// answers the first /callback request, prints its query string and exits.
export const CALLBACK_SERVER = [
  'import sys, time, http.server, urllib.parse',
  'port = int(sys.argv[1])',
  'result = []',
  'class H(http.server.BaseHTTPRequestHandler):',
  '    def do_GET(self):',
  '        u = urllib.parse.urlparse(self.path)',
  "        if u.path != '/callback':",
  '            self.send_response(404); self.end_headers(); return',
  '        result.append(u.query)',
  "        body = '<!doctype html><meta charset=\"utf-8\"><title>X</title><p>Claudeに戻ってください。このタブは閉じて構いません。</p>'.encode('utf-8')",
  '        self.send_response(200)',
  "        self.send_header('Content-Type', 'text/html; charset=utf-8')",
  "        self.send_header('Content-Length', str(len(body)))",
  '        self.end_headers()',
  '        self.wfile.write(body)',
  '    def log_message(self, *args):',
  '        pass',
  "server = http.server.HTTPServer(('127.0.0.1', port), H)",
  'server.timeout = 5',
  'deadline = time.time() + 300',
  'while not result and time.time() < deadline:',
  '    server.handle_request()',
  'server.server_close()',
  'if not result:',
  '    sys.exit(2)',
  'sys.stdout.write(result[0])',
].join('\n')

// A hashtag as people type it (`#猫`, `＃cat`, `cat`), without its mark.
export function normalizeTag(raw: string): string | null {
  const tag = raw.trim().replace(/^[#＃]+/, '')

  return /^[\p{L}\p{N}_]{1,100}$/u.test(tag) ? tag : null
}

export function tagQuery(tags: readonly string[]): string {
  const terms = tags.map(tag => `#${tag}`)

  return `${terms.length > 1 ? `(${terms.join(' OR ')})` : (terms[0] ?? '')} -is:retweet`
}

export const PROFILE_FIELDS = 'created_at,description,location,public_metrics,url,verified,verified_type,entities'

type ProfileBody = {
  data?: {
    id: string
    name: string
    username: string
    description?: string
    location?: string
    url?: string
    created_at?: string
    verified?: boolean
    verified_type?: string
    public_metrics?: { followers_count?: number; following_count?: number; tweet_count?: number }
    entities?: { url?: { urls?: UrlEntity[] }; description?: { urls?: UrlEntity[] } }
  }
}

export function parseProfile(body: unknown): Profile | null {
  const user = (body as ProfileBody)?.data
  if (!user?.id) return null
  const expand = (text: string, urls: UrlEntity[] | undefined) =>
    (urls ?? []).reduce((out, entity) => (entity.url ? out.replace(entity.url, entity.display_url ?? entity.expanded_url ?? entity.url) : out), text)
  const metrics = user.public_metrics ?? {}

  return {
    id: user.id,
    name: user.name,
    username: user.username,
    description: decodeEntities(expand(user.description ?? '', user.entities?.description?.urls)),
    location: user.location || null,
    url: user.url ? (user.entities?.url?.urls?.[0]?.expanded_url ?? user.url) : null,
    followers: metrics.followers_count ?? 0,
    following: metrics.following_count ?? 0,
    posts: metrics.tweet_count ?? 0,
    joined: user.created_at ?? null,
    isVerified: Boolean(user.verified || (user.verified_type && user.verified_type !== 'none')),
  }
}

export function joinedText(iso: string | null): string | null {
  const date = iso ? new Date(Date.parse(iso)) : null

  return date && Number.isFinite(date.getTime()) ? `${date.getFullYear()}年${date.getMonth() + 1}月から利用` : null
}

export function profileText(profile: Profile): string {
  const facts = [profile.location ? `📍 ${escapeMarkdown(profile.location)}` : '', profile.url ? `🔗 ${profile.url}` : '', joinedText(profile.joined) ? `📅 ${joinedText(profile.joined)}` : '']
    .filter(Boolean)
    .join('　')

  return [
    `**${escapeMarkdown(profile.name)}**${profile.isVerified ? ' ☑︎' : ''} [@${escapeMarkdown(profile.username)}](https://x.com/${profile.username})`,
    ...(profile.description ? [markdownBody(profile.description)] : []),
    ...(facts ? [facts] : []),
    `**${compactCount(profile.following)}** フォロー中　**${compactCount(profile.followers)}** フォロワー　**${compactCount(profile.posts)}** ポスト`,
  ].join('  \n')
}

// A single post's body (`/2/tweets/:id`) read as a one-post timeline.
export function parseSingle(body: unknown): Post[] {
  const value = body as { data?: TimelineItem; includes?: TimelineBody['includes'] }

  return value?.data ? parseTimeline({ data: [value.data], includes: value.includes }) : []
}

type ListBody = { data?: Array<{ id: string; name: string; member_count?: number; private?: boolean; description?: string }> }

export function parseLists(body: unknown): ListInfo[] {
  return ((body as ListBody)?.data ?? []).map(list => ({
    id: list.id,
    name: list.name,
    members: list.member_count ?? null,
    isPrivate: Boolean(list.private),
    description: list.description ?? '',
  }))
}

// A count as X writes it for people: `12,345`, `1.2万`, `12.3K`, `1.5M posts`.
export function parseCount(text: string): number | null {
  const match = /([\d.,]+)\s*(万|億|K|M|B)?/i.exec(text)
  if (!match?.[1]) return null
  const base = Number(match[1].replace(/,/g, ''))
  if (!Number.isFinite(base)) return null
  const unit = (match[2] ?? '').toUpperCase()
  const scale = unit === '万' ? 1e4 : unit === '億' ? 1e8 : unit === 'K' ? 1e3 : unit === 'M' ? 1e6 : unit === 'B' ? 1e9 : 1

  return Math.round(base * scale)
}

type TrendBody = { data?: Array<{ trend_name?: string; post_count?: number | string; category?: string; trending_since?: string }> }

export function parseTrends(body: unknown): TrendInfo[] {
  return ((body as TrendBody)?.data ?? []).flatMap(trend => {
    if (!trend.trend_name) return []
    const count = typeof trend.post_count === 'number' ? trend.post_count : parseCount(String(trend.post_count ?? ''))

    return [{ name: trend.trend_name, posts: count, category: trend.category ?? null }]
  })
}

// `/x p 本文 --image ~/a.png --image b.jpg`: the text, and the pictures to attach.
export function parsePostArgs(raw: string): { text: string; images: string[] } {
  const images: string[] = []
  const text = raw
    .replace(/(?:^|\s)--image\s+("([^"]+)"|(\S+))/g, (_all, _whole, quoted: string | undefined, bare: string | undefined) => {
      images.push(quoted ?? bare ?? '')

      return ''
    })
    .trim()

  return { text, images: images.filter(Boolean) }
}

export const IMAGE_TYPES: Record<string, string> = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp' }
export const IMAGE_LIMIT = 5 * 1024 * 1024

// A picture path curl's form syntax reads whole: no `;` `,` `"` or newline.
export function imagePathProblem(path: string): string | null {
  if (!path.startsWith('/')) return 'フルパスで指定してください'
  if (/[;,"\n\r]/.test(path)) return 'パスに ; , " は使えません'
  const ext = path.split('.').pop()?.toLowerCase() ?? ''

  return IMAGE_TYPES[ext] ? null : '対応する画像は png / jpg / gif / webp です'
}

